SOURCES={'reference43.py': '"""N1 x W2 factorial; unchanged active original core and 29 W2 branch."""\nimport sys\nfrom pathlib import Path\nsys.path.insert(0,str(Path(__file__).parent/\'provenance/source\'))\nimport torch\nfrom torch import nn\nfrom common.model import RestoredPansharpeningNet\nARMS=(\'C0\',\'C1\',\'C2\',\'C3\')\nclass Block(nn.Module):\n    def __init__(self,c):\n        super().__init__();self.net=nn.Sequential(nn.Conv2d(c,c,3,padding=1),nn.ReLU(inplace=True),nn.Conv2d(c,c,3,padding=1))\n    def forward(self,x):return x+self.net(x)\nclass Parallel(nn.Module):\n    def __init__(self,original):\n        super().__init__();self.original=original\n        self.branch=nn.Sequential(nn.PixelUnshuffle(2),nn.Conv2d(256,128,1),*[Block(128) for _ in range(8)],nn.Conv2d(128,256,1),nn.PixelShuffle(2))\n        nn.init.zeros_(self.branch[-2].weight);nn.init.zeros_(self.branch[-2].bias)\n    def forward(self,x):return self.original(x)+self.branch(x)\nclass Model(nn.Module):\n    def __init__(self,arm,seed=42):\n        super().__init__()\n        if arm not in ARMS:raise ValueError(arm)\n        self.arm=arm\n        with torch.random.fork_rng(devices=[]):\n            torch.manual_seed(seed);self.core=RestoredPansharpeningNet(4,4)\n            if arm in (\'C2\',\'C3\'):self.core.backbone=Parallel(self.core.backbone)\n    def forward(self,pan,lms,ms):\n        if self.arm in (\'C0\',\'C2\'):return self.core(pan,lms,ms)\n        with torch.autocast(device_type=ms.device.type,enabled=False):\n            variance,mean=torch.var_mean(ms.float(),dim=(1,2,3),correction=0,keepdim=True)\n            scale=variance.clamp_min(0).sqrt().clamp_min(.01)\n            inputs=tuple((x.float()-mean)/scale for x in (pan,lms,ms))\n        y=self.core(*inputs)\n        with torch.autocast(device_type=ms.device.type,enabled=False):return y.float()*scale+mean\n', 'common/model.py': '"""Minimal forward-path repair around the untouched official network.py.\n\nThe official forward(pan, lms) references an undefined `ms`. Its three\nspatial stages require PAN and interpolated LMS at full resolution, plus\nthe original MS at one-quarter resolution. This adapter supplies that input\nexplicitly and retains the original modules, parameter names and operations.\n"""\n\nimport importlib.util\nfrom pathlib import Path\n\nimport torch\nfrom torch import nn\n\n\nUPSTREAM_PATH = Path(__file__).resolve().parents[1] / "references/upstream/network.py"\n\n\ndef _upstream_model():\n    if not UPSTREAM_PATH.is_file():\n        raise FileNotFoundError(f"Initialize the official SSA-MRN submodule: {UPSTREAM_PATH}")\n    spec = importlib.util.spec_from_file_location("ssamrn_official_network", UPSTREAM_PATH)\n    module = importlib.util.module_from_spec(spec)\n    spec.loader.exec_module(module)\n    return module.PansharpeningNet\n\n\nclass DirectMLPReLU(nn.PReLU):\n    """Equivalent PReLU expression avoiding a DirectML batch backward error."""\n\n    def forward(self, input):\n        slope = self.weight.view(1, -1, 1, 1)\n        return torch.where(input > 0, input, slope * input)\n\n\nclass RestoredPansharpeningNet(_upstream_model()):\n    """Official layers with an explicit low-resolution MS input."""\n\n    def __init__(self, channels, ssai_dimension=4, guide_channels=1):\n        super().__init__(channels)\n        if guide_channels not in (1, 3):\n            raise ValueError("guide_channels must be 1 (PAN) or 3 (RGB)")\n        self.guide_channels = guide_channels\n        if guide_channels == 3:\n            self.conv1t1 = nn.Conv2d(3, 3, 3, padding=1)\n            self.cov2t64 = nn.Conv2d(channels + 6, 64, 3, padding=1)\n            for blocks in (self.SSA_blocks, self.SSA_blocks1, self.SSA_blocks2):\n                for block in blocks:\n                    block.conv1t6 = nn.Conv2d(3, 4, 3, padding=1)\n        if ssai_dimension < 1:\n            raise ValueError("ssai_dimension must be positive")\n        self.ssai_dimension = ssai_dimension\n        if ssai_dimension == 4:\n            return  # Preserve the published upstream architecture and existing checkpoints.\n\n        # The upstream code hard-codes K=4, while the paper specifies K=6.\n        # Resize only the layers used by the restored forward path; leave upstream untouched.\n        self.fixed = ssai_dimension\n        for blocks in (self.SSA_blocks, self.SSA_blocks1, self.SSA_blocks2):\n            for block in blocks:\n                block.fixed = ssai_dimension\n                block.conv1t6 = nn.Conv2d(guide_channels, ssai_dimension, 3, padding=1)\n                block.conv6t6 = nn.Conv2d(ssai_dimension, ssai_dimension, 3, padding=1)\n                block.conv7t6_3 = nn.Conv2d(channels + 1, ssai_dimension, 3, padding=1)\n        for name in ("conv48tnum1", "conv48tnum2", "conv48tnum3"):\n            setattr(self, name, nn.Conv2d(ssai_dimension * channels, channels, 3, padding=1))\n\n    def use_directml_prelu(self):\n        """Keep PReLU weights/checkpoints while using a DirectML-safe backward."""\n        for name, module in self.named_modules():\n            if not name or not isinstance(module, nn.PReLU):\n                continue\n            parent = self.get_submodule(name.rpartition(".")[0]) if "." in name else self\n            replacement = DirectMLPReLU(module.num_parameters)\n            with torch.no_grad():\n                replacement.weight.copy_(module.weight)\n            setattr(parent, name.rpartition(".")[2], replacement)\n\n    def _attend(self, pan, features, ms, blocks, fusion, activation):\n        outputs = []\n        for band in range(self.channels):\n            band_input = torch.cat([features, ms[:, band : band + 1]], dim=1)\n            outputs.append(blocks[band](pan, band_input))\n        return activation(fusion(torch.cat(outputs, dim=1)))\n\n    def forward(self, pan, lms, ms):\n        if pan.ndim != 4 or lms.ndim != 4 or ms.ndim != 4:\n            raise ValueError("Expected NCHW tensors for pan, lms, and ms")\n        n, channels, h, w = lms.shape\n        if channels != self.channels or h % 4 or w % 4 or min(h, w) < 4:\n            raise ValueError(f"Invalid LMS shape: {tuple(lms.shape)}")\n        if pan.shape != (n, self.guide_channels, h, w) or ms.shape != (n, channels, h // 4, w // 4):\n            raise ValueError("Expected guide at LMS resolution and MS at 1/4 resolution")\n\n        pan_down_up = self.upsample1(self.downsample1(pan))\n        pan_updown = self.prelu(self.conv1t1(pan_down_up))\n        features = torch.cat([lms, pan, pan_updown], dim=1)\n        features = self.backbone(self.cov2t64(features))\n        res = self.conv64t48(features) + lms\n\n        pan_ms = self._attend(pan, res, lms, self.SSA_blocks, self.conv48tnum1, self.prelu1)\n        res = res + pan_ms\n\n        res_half = self.downsample100(res)\n        ms_half = self.upsample100(ms)\n        pan_half = self.downsample100(pan)\n        pan_ms = self._attend(pan_half, res_half, ms_half, self.SSA_blocks1, self.conv48tnum2, self.prelu2)\n        res_half = res_half + pan_ms\n\n        res_quarter = self.downsample200(res_half)\n        pan_quarter = self.downsample2(pan)\n        pan_ms = self._attend(pan_quarter, res_quarter, ms, self.SSA_blocks2, self.conv48tnum3, self.prelu3)\n\n        output = self.conv2ctc1(torch.cat([ms, pan_ms], dim=1))\n        output = self.conv2ctc2(torch.cat([self.upsample101(output), res_half], dim=1))\n        output = self.conv2ctc3(torch.cat([self.upsample102(output), res], dim=1))\n        return output\n\n', 'common/metrics.py': '"""PanCollection RR/FR metrics, following DLPan-Toolbox definitions.\n\nFR PAN resizing uses scikit-image\'s antialiased bicubic approximation to\nMATLAB imresize; D_s/QNR must be parity-checked before a strict paper claim.\n"""\n\nimport numpy as np\nfrom scipy.ndimage import convolve, convolve1d\nfrom skimage.transform import resize\n\n\ndef _chw(image):\n    array = np.asarray(image, dtype=np.float64)\n    if array.ndim != 3 or not np.isfinite(array).all():\n        raise ValueError("Expected finite CHW image")\n    return array\n\n\ndef _onion(a, b):\n    """Cayley-Dickson multiplication used by MATLAB onions_quality."""\n    n = a.shape[-1]\n    if n == 1:\n        return a * b\n    half = n // 2\n    x, y = a[..., :half], a[..., half:]\n    z, w = b[..., :half], b[..., half:]\n    cy = np.concatenate((y[..., :1], -y[..., 1:]), axis=-1)\n    cw = np.concatenate((w[..., :1], -w[..., 1:]), axis=-1)\n    if n == 2:\n        return np.concatenate((x * z - w * y, x * w + z * y), axis=-1)\n    cx = np.concatenate((x[..., :1], -x[..., 1:]), axis=-1)\n    return np.concatenate((_onion(x, z) - _onion(w, cy), _onion(cx, w) + _onion(z, y)), axis=-1)\n\n\ndef q2n(reference, fused, block=32):\n    """Q4/Q8 with nonoverlapping 32-pixel blocks, matching q2n.m here."""\n    reference, fused = _chw(reference), _chw(fused)\n    if reference.shape != fused.shape:\n        raise ValueError("Q2n shapes differ")\n    channels, height, width = reference.shape\n    if height % block or width % block or channels & (channels - 1):\n        raise ValueError("Q2n requires block-aligned images and power-of-2 bands")\n    def blocks(image):\n        # MATLAB uint16 saturates/rounds values before the hypercomplex index.\n        image = np.rint(np.clip(image, 0, 65535)).transpose(1, 2, 0)\n        return image.reshape(height // block, block, width // block, block, channels).transpose(0, 2, 1, 3, 4).reshape(-1, block, block, channels)\n    a, b = blocks(reference), blocks(fused)\n    mean_a = a.mean(axis=(1, 2), keepdims=True)\n    std_a = a.std(axis=(1, 2), ddof=1, keepdims=True)\n    std_a = np.where(std_a == 0, np.finfo(float).eps, std_a)\n    a = (a - mean_a) / std_a + 1\n    b = (b - mean_a) / std_a + 1\n    b[..., 1:] *= -1\n    m1, m2 = a.mean(axis=(1, 2)), b.mean(axis=(1, 2))\n    m1_sq, m2_sq = np.sum(m1 * m1, axis=-1), np.sum(m2 * m2, axis=-1)\n    bias = np.divide(2 * np.sqrt(m1_sq * m2_sq), m1_sq + m2_sq,\n                     out=np.zeros_like(m1_sq), where=(m1_sq + m2_sq) != 0)\n    n = block * block\n    variance_term = n / (n - 1) * (\n        np.mean(np.sum(a * a + b * b, axis=-1), axis=(1, 2)) - m1_sq - m2_sq\n    )\n    quality = np.empty((len(a), channels), dtype=np.float64)\n    nonzero = np.abs(variance_term) > 1e-12\n    quality[~nonzero] = 0\n    quality[~nonzero, -1] = bias[~nonzero]\n    if np.any(nonzero):\n        product_mean = _onion(a[nonzero], b[nonzero]).mean(axis=(1, 2))\n        mean_product = _onion(m1[nonzero], m2[nonzero])\n        quality[nonzero] = (product_mean - mean_product) * (n / (n - 1) * bias[nonzero] * 2 / variance_term[nonzero])[:, None]\n    return float(np.linalg.norm(quality, axis=-1).mean())\n\n\ndef rr_metrics(reference, fused, *, ratio=4):\n    """Return per-image RR metrics, not an image-concatenated score."""\n    reference, fused = _chw(reference), _chw(fused)\n    if reference.shape != fused.shape:\n        raise ValueError("RR shapes differ")\n    diff = fused - reference\n    dot = np.sum(reference * fused, axis=0)\n    norms = np.linalg.norm(reference, axis=0) * np.linalg.norm(fused, axis=0)\n    valid = norms > 0\n    sam = float(np.degrees(np.arccos(np.clip(dot[valid] / norms[valid], -1, 1))).mean())\n    means = reference.mean(axis=(1, 2))\n    band_mse = np.mean(diff * diff, axis=(1, 2))\n    ergas = float(100 / ratio * np.sqrt(np.mean(band_mse / np.maximum(means * means, 1e-30))))\n    # MATLAB SCC: Sobel gradient magnitudes on a 1-pixel cropped image.\n    sobel = np.array([[1, 2, 1], [0, 0, 0], [-1, -2, -1]], dtype=float)\n    def gradients(image):\n        image = image[:, 1:-1, 1:-1]\n        gy = np.stack([convolve(band, sobel, mode="constant") for band in image])\n        gx = np.stack([convolve(band, sobel.T, mode="constant") for band in image])\n        return np.hypot(gx, gy)\n    a, b = gradients(reference), gradients(fused)\n    scc = float(np.sum(a * b) / np.sqrt(np.sum(a * a) * np.sum(b * b)))\n    # The paper does not specify its PSNR convention. Use the empirically\n    # closest documented choice: per-band PSNR at peak 2047, then average.\n    psnr = float(np.mean(10 * np.log10(2047 * 2047 / np.maximum(band_mse, 1e-30))))\n    return {"SAM": sam, "ERGAS": ergas, "PSNR": psnr,\n            "SCC": scc, "Q2n": q2n(reference, fused)}\n\n\ndef _block_uqi(a, b, block=32):\n    """Average MATLAB uqi over nonoverlapping blocks."""\n    height, width = a.shape\n    if a.shape != b.shape or height % block or width % block:\n        raise ValueError("UQI shapes are not block aligned")\n    def group(image):\n        return image.reshape(height // block, block, width // block, block).transpose(0, 2, 1, 3).reshape(-1, block * block)\n    x, y = group(a), group(b)\n    mx, my = x.mean(axis=1), y.mean(axis=1)\n    vx, vy = x.var(axis=1, ddof=1), y.var(axis=1, ddof=1)\n    cov = np.sum((x - mx[:, None]) * (y - my[:, None]), axis=1) / (x.shape[1] - 1)\n    denominator = (vx + vy) * (mx * mx + my * my)\n    quality = np.divide(4 * cov * mx * my, denominator,\n                        out=np.zeros_like(mx), where=np.abs(denominator) > 1e-30)\n    return float(quality.mean())\n\n\ndef _interp23tap(image, ratio=4):\n    coeff = 2 * np.array([.5, .305334091185, 0, -.072698593239, 0, .021809577942,\n                          0, -.005192756653, 0, .000807762146, 0, -.000060081482])\n    coeff = np.r_[coeff[:0:-1], coeff]\n    for stage in range(int(np.log2(ratio))):\n        up = np.zeros((image.shape[0] * 2, image.shape[1] * 2))\n        offset = 1 if stage == 0 else 0\n        up[offset::2, offset::2] = image\n        image = convolve1d(convolve1d(up, coeff, axis=0, mode="wrap"), coeff, axis=1, mode="wrap")\n    return image\n\n\ndef fr_metrics(fused, lms, ms, pan, *, ratio=4, block=32):\n    """Toolbox-style QNR; PAN antialias resize is not MATLAB-bit-exact."""\n    fused, lms, ms = _chw(fused), _chw(lms), _chw(ms)\n    pan = np.asarray(pan, dtype=np.float64).squeeze()\n    if fused.shape != lms.shape or pan.shape != fused.shape[1:] or ms.shape[1:] != (pan.shape[0] // ratio, pan.shape[1] // ratio):\n        raise ValueError("FR input shapes differ")\n    channels = fused.shape[0]\n    spectral = [abs(_block_uqi(fused[i], fused[j], block) - _block_uqi(lms[i], lms[j], block))\n                for i in range(channels) for j in range(i + 1, channels)]\n    down = resize(pan, ms.shape[1:], order=3, mode="reflect", anti_aliasing=True, preserve_range=True)\n    pan_filtered = _interp23tap(down, ratio)\n    spatial = [abs(_block_uqi(fused[i], pan, block) - _block_uqi(lms[i], pan_filtered, block))\n               for i in range(channels)]\n    d_lambda, d_s = float(np.mean(spectral)), float(np.mean(spatial))\n    return {"D_lambda": d_lambda, "D_s": d_s, "QNR": (1 - d_lambda) * (1 - d_s)}\n', 'references/upstream/network.py': 'import torch\nimport torch.nn as nn\nimport torch.nn.functional as F\n\n\nclass ResBlock(nn.Module):\n    def __init__(self, in_channels):\n        super(ResBlock, self).__init__()\n        self.conv1 = nn.Conv2d(in_channels, in_channels, kernel_size=3, padding=1, bias=False)\n        self.bn1 = nn.BatchNorm2d(in_channels)\n        self.conv2 = nn.Conv2d(in_channels, in_channels, kernel_size=3, padding=1, bias=False)\n        self.bn2 = nn.BatchNorm2d(in_channels)\n\n    def forward(self, x):\n        residual = x\n        out = self.conv1(x)\n        out = F.relu(self.bn1(out))\n        out = self.conv2(out)\n        out = self.bn2(out)\n        out += residual\n        out = F.relu(out)\n        return out\n\n\nclass Resbackbone(nn.Module):\n    def __init__(self, in_channels):\n        super(Resbackbone, self).__init__()\n        channel = 64\n        self.conv1 = nn.Conv2d(in_channels=in_channels, out_channels=channel, kernel_size=3, padding=1, stride=1,\n                               bias=True)\n\n        self.res1 = ResBlock(channel)\n        self.res2 = ResBlock(channel)\n        self.res3 = ResBlock(channel)\n        self.res4 = ResBlock(channel)\n\n        self.backbone = nn.Sequential(\n            self.res1,\n            self.res2,\n            self.res3,\n            self.res4,\n\n        )\n        self.relu = nn.ReLU(inplace=True)\n        self.conv2 = nn.Conv2d(in_channels=channel, out_channels=1, stride=1, kernel_size=3, padding=1,\n                               bias=True)\n\n    def forward(self, x):\n        x = self.relu(self.conv1(x))\n        x = self.backbone(x)\n        x = self.conv2(x)\n        return x\n\n\nclass Resblock(nn.Module):\n    def __init__(self):\n        super(Resblock, self).__init__()\n\n        channel = 64\n\n        self.conv20 = nn.Conv2d(in_channels=channel, out_channels=channel, padding=1, kernel_size=3, stride=1,\n                                bias=True)\n        self.conv21 = nn.Conv2d(in_channels=channel, out_channels=channel, padding=1, kernel_size=3, stride=1,\n                                bias=True)\n        self.relu = nn.ReLU(\n            inplace=True) \n    def forward(self, x):\n        rs1 = self.relu(self.conv20(x))\n        rs2 = self.conv21(rs1)  \n        # print(f"rs2:{rs2.shape},x:{x.shape}")\n        rs = torch.add(x, rs2) \n        return rs\n\n\nclass SSA(nn.Module):\n    def __init__(self,channels):\n        super(SSA, self).__init__()\n\n        self.fixed  = 4\n\n\n        self.conv1t6 = nn.Conv2d(in_channels=1, out_channels=self.fixed , kernel_size=3, stride=1, padding=1,\n                                 bias=True)\n        self.conv6t12 = nn.Conv2d(in_channels=6, out_channels=12, kernel_size=3, stride=1, padding=1,\n                                  bias=True)\n        self.conv6t6 = nn.Conv2d(in_channels=self.fixed , out_channels=self.fixed , kernel_size=3, stride=1, padding=1,\n                                 bias=True)\n        self.relu = nn.ReLU()\n        self.conv7t6_3 = nn.Conv2d(in_channels=channels + 1, out_channels=self.fixed, kernel_size=3, stride=1,\n                                   padding=1, bias=True)\n\n    def forward(self, pan, ms_pro):  # ms_pro 6xhxw  pan 1xhxw\n        pan_guide = self.relu(self.conv1t6(pan))\n        pan_guide = self.conv6t6(pan_guide)  # 6*h*w\n        ms_pro = self.conv7t6_3(ms_pro)\n        # pan reshape -> 6xhw\n        # ms_pro reshape -> 6xhw  -> transpose > 6xwh\n        b, c, h, w = ms_pro.size()\n        pan_reshape = pan_guide.view(b, c, -1)  # 6xhw\n        ms_pro_transpose = ms_pro.permute(0, 1, 3, 2)\n        ms_pro_reshape = ms_pro_transpose.reshape(b, c, -1)  # 6xhw\n        # print(ms_pro_reshape.shape)\n        # ms使用了转置\n\n        # pan_matrix * ms_pro_matrix -> 6xhwxwh -> softmax ->6xhxw\n        pan_matrix = torch.mul(pan_reshape, ms_pro_reshape)  # b x c x hw x wh\n        # print(pan_matrix.shape)\n        pan_matrix = pan_matrix.view(b, c, h, w)\n        # print(pan_matrix.shape)\n        pan_matrix = pan_matrix.permute(0, 1, 3, 2)\n        pan_matrix = pan_matrix.contiguous().view(b, c, -1)\n       \n        pan_matrix = F.softmax(pan_matrix, dim=-1)\n        # print(pan_matrix.shape)\n\n        # transpose_R * ms_pro_matrix -> 6xhwxwh -> reshape -> output= 6xhxw\n        output = torch.mul(pan_reshape, pan_matrix)  # b x c x hw\n        output = output.contiguous().view(b, c, h, w)  # reshape to 6xhxw\n\n        # print(f"res{res.shape}")\n        return output\n\n\n\n\n\n\n\nclass PansharpeningNet(nn.Module):\n    def __init__(self, channels):\n        super(PansharpeningNet, self).__init__()\n\n        self.fixed = 4\n\n        # Downsampling and Upsampling layers\n        self.downsample1 = nn.Upsample(scale_factor=0.5, mode=\'bilinear\', align_corners=True)\n        self.downsample2 = nn.Upsample(scale_factor=0.25, mode=\'bilinear\', align_corners=True)\n        self.upsample1 = nn.Upsample(scale_factor=2, mode=\'bilinear\', align_corners=True)\n        self.upsample2 = nn.Upsample(scale_factor=4, mode=\'bilinear\', align_corners=True)\n        self.downsample200 = nn.Upsample(scale_factor=0.5, mode=\'bilinear\', align_corners=True)\n        # Feature extraction and fusion layers with individual names\n        self.prelu1 = nn.PReLU()\n        self.prelu2 = nn.PReLU()\n        self.prelu3 = nn.PReLU()\n\n        self.conv1t64 = nn.Conv2d(1, 64, kernel_size=3, padding=1)\n        self.conv64tnum = nn.Conv2d(64, channels, kernel_size=3, padding=1)\n        self.convnumt64 = nn.Conv2d(channels, 64, kernel_size=3, padding=1)\n\n        self.conv1t64_pan = nn.Conv2d(1, 64, kernel_size=3, padding=1)\n        self.conv64tnum_pan = nn.Conv2d(64, channels, kernel_size=3, padding=1)\n\n        self.convnum3tnum1 = nn.Conv2d(channels * 3, channels, kernel_size=3, padding=1)\n        self.convnum3tnum2 = nn.Conv2d(channels * 3, channels, kernel_size=3, padding=1)\n        self.convnum3tnum3 = nn.Conv2d(channels * 3, channels, kernel_size=3, padding=1)\n\n        self.conv48tnum1 = nn.Conv2d(in_channels=self.fixed * channels, out_channels=channels, kernel_size=3, stride=1,\n                                     padding=1, bias=True)\n        self.conv48tnum2 = nn.Conv2d(in_channels=self.fixed * channels, out_channels=channels, kernel_size=3, stride=1,\n                                     padding=1, bias=True)\n        self.conv48tnum3 = nn.Conv2d(in_channels=self.fixed * channels, out_channels=channels, kernel_size=3, stride=1,\n                                     padding=1, bias=True)\n\n        self.conv7t6_1 = nn.Conv2d(in_channels=channels + 1, out_channels=self.fixed, kernel_size=3, stride=1,\n                                   padding=1, bias=True)\n        self.conv7t6_2 = nn.Conv2d(in_channels=channels + 1, out_channels=self.fixed, kernel_size=3, stride=1,\n                                   padding=1, bias=True)\n        self.conv7t6_3 = nn.Conv2d(in_channels=channels + 1, out_channels=self.fixed, kernel_size=3, stride=1,\n                                   padding=1, bias=True)\n\n        self.conv2ctc1 = nn.Conv2d(in_channels=channels * 2, out_channels=channels, kernel_size=3, stride=1, padding=1,\n                                   bias=True)\n        self.conv2ctc2 = nn.Conv2d(in_channels=channels * 2, out_channels=channels, kernel_size=3, stride=1, padding=1,\n                                   bias=True)\n        self.conv2ctc3 = nn.Conv2d(in_channels=channels * 2, out_channels=channels, kernel_size=3, stride=1, padding=1,\n                                   bias=True)\n\n        self.SSA_blocks = nn.ModuleList([SSA(channels=channels) for _ in range(channels)])\n\n        self.SSA_blocks1 = nn.ModuleList([SSA(channels=channels) for _ in range(channels)])\n        self.SSA_blocks2 = nn.ModuleList([SSA(channels=channels) for _ in range(channels)])\n        self.conv1t1 = nn.Conv2d(in_channels=1, out_channels=1, kernel_size=3, stride=1, padding=1, bias=True)\n        self.cov2t64 = nn.Conv2d(in_channels=2 + channels, out_channels=64, kernel_size=3, stride=1, padding=1,\n                                 bias=True)\n\n        self.res1 = Resblock()\n        self.res2 = Resblock()\n        self.res3 = Resblock()\n        self.res4 = Resblock()\n\n        self.backbone = nn.Sequential(\n                self.res1,\n                self.res2,\n                self.res3,\n                self.res4,\n            )\n        self.conv64t48 = nn.Conv2d(in_channels=64, out_channels=channels, kernel_size=3, stride=1, padding=1, bias=True)\n        self.fixed = 4;\n\n        # Downsampling and Upsampling layers\n        self.downsample = nn.Upsample(scale_factor=0.5, mode=\'bilinear\', align_corners=True)\n        self.upsample = nn.Upsample(scale_factor=2, mode=\'bilinear\', align_corners=True)\n        self.downsample1 = nn.Upsample(scale_factor=0.25, mode=\'bilinear\', align_corners=True)\n        self.upsample1 = nn.Upsample(scale_factor=4, mode=\'bilinear\', align_corners=True)\n        self.upsample100 = nn.Upsample(scale_factor=2, mode=\'bilinear\', align_corners=True)\n        self.downsample100 = nn.Upsample(scale_factor=0.5, mode=\'bilinear\', align_corners=True)\n        self.upsample101  = nn.Upsample(scale_factor=2, mode=\'bilinear\', align_corners=True)\n        self.upsample102\\\n            = nn.Upsample(scale_factor=2, mode=\'bilinear\', align_corners=True)\n        # Fusion layers\n        self.resblock = Resblock()\n        self.prelu = nn.PReLU()\n        self.conv1t64 = nn.Conv2d(1, 64, kernel_size=3, padding=1)\n        self.conv64tnum = nn.Conv2d(64, channels, kernel_size=3, padding=1)\n        self.convnumt64 = nn.Conv2d(channels, 64, kernel_size=3, padding=1)\n\n        self.conv1t64bf2 = nn.Conv2d(1, 64, kernel_size=3, padding=1)\n        self.conv64tnumbf2 = nn.Conv2d(64, channels, kernel_size=3, padding=1)\n        self.convnumt64bf2 = nn.Conv2d(channels, 64, kernel_size=3, padding=1)\n\n        self.convnumtnum = nn.Conv2d(channels * 3, channels * 3, kernel_size=3, padding=1)\n        self.convctc1 = nn.Conv2d(channels, channels, kernel_size=3, padding=1)  # convctc1\n        self.convctc2 = nn.Conv2d(channels, channels, kernel_size=3, padding=1)  # convctc2\n        self.convnum3tnum = nn.Conv2d(channels * 3, channels, kernel_size=3, padding=1)\n        self.relu = nn.ReLU()\n\n        self.conv2 = nn.Conv2d(in_channels=channels, out_channels=channels * 6, stride=1, kernel_size=3, padding=1,\n                               bias=True)\n\n        self.SSA_blocks = nn.ModuleList(\n            [SSA(channels=channels) for _ in range(channels)])  # Adding multi-scale blocks\n\n        self.conv48tnum1 = nn.Conv2d(in_channels=self.fixed * channels, out_channels=channels, kernel_size=3, stride=1,\n                                     padding=1, bias=True)\n        self.conv48tnum2 = nn.Conv2d(in_channels=self.fixed * channels, out_channels=channels, kernel_size=3, stride=1,\n                                     padding=1, bias=True)\n\n        self.conv48t48_1 = nn.Conv2d(in_channels=6 * channels, out_channels=6 * channels, kernel_size=3, stride=1,\n                                     padding=1, bias=True)\n        self.conv48t48_2 = nn.Conv2d(in_channels=channels, out_channels=channels, kernel_size=3, stride=1, padding=1,\n                                     bias=True)\n        self.conv48t48_3 = nn.Conv2d(in_channels=6 * channels, out_channels=6 * channels, kernel_size=3, stride=1,\n                                     padding=1, bias=True)\n\n        self.conv7t6 = nn.Conv2d(in_channels=channels + 1, out_channels=self.fixed, kernel_size=3, stride=1, padding=1,\n                                 bias=True)\n\n        self.convnum3tn64 = nn.Conv2d(in_channels=channels * 3, out_channels=64, kernel_size=3, stride=1, padding=1,\n                                      bias=True)\n\n        self.group_size = 6 \n        self.channels = channels\n        self.cov2t64 = nn.Conv2d(in_channels=2 + channels, out_channels=64, kernel_size=3, stride=1, padding=1,\n                                 bias=True)\n        self.conv64t48 = nn.Conv2d(in_channels=64, out_channels=channels, kernel_size=3, stride=1, padding=1, bias=True)\n        self.conv1t1 = nn.Conv2d(in_channels=1, out_channels=1, kernel_size=3, stride=1, padding=1, bias=True)\n\n        self.convnumt48 = nn.Conv2d(in_channels=channels, out_channels=channels, kernel_size=3, stride=1, padding=1,\n                                    bias=True)\n\n        self.relu = nn.ReLU(inplace=True)\n        self.conv8t4 = nn.Conv2d(in_channels=8, out_channels=channels, kernel_size=3, stride=1, padding=1,\n                                    bias=True)\n\n\n\n   \n    def forward(self, pan, lms):\n        # Stage 1: Downsample and upsample each input\n        pan_down_up = self.upsample1(self.downsample1(pan))\n        pan_updown = self.prelu(self.conv1t1(pan_down_up))\n        input = torch.cat([lms, pan, pan_updown], dim=1)\n\n        y = self.cov2t64(input)\n        y = self.backbone(y)\n        y1 = self.conv64t48(y)\n        rs = y1 + lms\n\n        # Process input channels separately\n        split_input = [rs[:, i:i + self.group_size, :, :] for i in range(0, 48, self.group_size)]\n        split_ms = [lms[:, i, :, :].unsqueeze(1) for i in range(self.channels)]\n\n        outputs = []\n        for input_channel, ms_channel, ssa in zip(split_input, split_ms, self.SSA_blocks):\n            x = torch.cat([rs, ms_channel], dim=1)\n\n            ms_one = ssa(pan, x)\n            outputs.append(ms_one)\n\n        pan_ms = torch.cat(outputs, dim=1)\n        pan_ms = self.prelu1(self.conv48tnum1(pan_ms))\n        fsm_msb = rs + pan_ms\n        res = fsm_msb\n\n        res_down = self.downsample100(res)\n\n        # Stage 2: MS upsample and next stage fusion\n        ms_up = self.upsample100(ms)\n        rs = res_down\n\n        split_input = [rs[:, i:i + self.group_size, :, :] for i in range(0, 48, self.group_size)]\n        split_ms = [ms_up[:, i, :, :].unsqueeze(1) for i in range(self.channels)]\n\n        outputs = []\n        for input_channel, ms_channel, ssa in zip(split_input, split_ms, self.SSA_blocks1):\n            x = torch.cat([rs, ms_channel], dim=1)\n\n            pan_down = self.downsample100(pan)\n            ms_one = ssa(pan_down, x)\n            outputs.append(ms_one)\n\n        pan_ms = torch.cat(outputs, dim=1)\n        pan_ms = self.prelu2(self.conv48tnum2(pan_ms))\n        fsm_msb = rs + pan_ms\n        res_down = fsm_msb\n\n        # Stage 3: Small scale stage\n        res_small = self.downsample200(res_down)\n        rs = res_small\n\n        split_input = [rs[:, i:i + self.group_size, :, :] for i in range(0, 48, self.group_size)]\n        split_ms = [ms[:, i, :, :].unsqueeze(1) for i in range(self.channels)]\n\n        outputs = []\n        for input_channel, ms_channel, ssa in zip(split_input, split_ms, self.SSA_blocks2):\n            x = torch.cat([rs, ms_channel], dim=1)\n\n            pan_down = self.downsample2(pan)\n            ms_one = ssa(pan_down, x)\n            outputs.append(ms_one)\n\n        pan_ms = torch.cat(outputs, dim=1)\n        pan_ms = self.prelu3(self.conv48tnum3(pan_ms))\n        res_small = pan_ms\n\n        # Output processing\n        ms_output = ms\n        ms_output = torch.cat([ms_output, res_small], dim=1)\n        ms_output = self.conv2ctc1(ms_output)\n\n        ms_output = self.upsample101(ms_output)\n        ms_output = torch.cat([ms_output, res_down], dim=1)\n        ms_output = self.conv2ctc2(ms_output)\n\n        ms_output = self.upsample102(ms_output)\n        ms_output = torch.cat([ms_output, res], dim=1)\n        ms_output = self.conv2ctc3(ms_output)\n\n\n\n\n        return ms_output\n\n', 'common/evaluation_protocol.py': '"""Ground-truth based evaluation protocol (criteria v2, experiment 47).\n\nRR       : PanCollection RR test scenes as provided (GT available).\nRR2      : RR test scenes degraded once more by the dataset\'s own Wald operator; GT = the RR MS.\nFR_WALD  : FR test scenes degraded by the same operator; GT = the native FR MS.\nFR_OBS   : interior RMSE (DN) between the observation of the FR output and the FR MS.\nFR QNR / D_lambda / D_s are still computed with common/metrics.fr_metrics but are reported only\n(experiment 46: on QB they rank the ground truth below model outputs).\n\nDegradation: MS by common/observation.SensorObservation (DLPan MTF, x4, phase 2; experiment 3 audit),\nPAN by the DLPan MTF_PAN filter (QB GNyq 0.15, 41 taps) and the same x4 phase-2 sampling,\nLMS by common/interpolation.interp23tap (reproduces the H5 LMS of the test scenes exactly).\n"""\nimport numpy as np\nimport torch\nfrom torch.nn import functional as F\n\nfrom common.interpolation import interp23tap\nfrom common.metrics import fr_metrics, rr_metrics\nfrom common.observation import SensorObservation\n\nRATIO = 4\nPAN_GNYQ = {\'QB\': 0.15}\nOBS_MARGIN = 5\n\n\ndef _pan_kernel(gain, ratio=RATIO, size=41):\n    coordinate = np.arange(size) - (size - 1) / 2\n    y, x = np.meshgrid(coordinate, coordinate, indexing=\'ij\')\n    window = np.interp(np.sqrt(x * x + y * y), np.arange(size // 2 + 1), np.kaiser(size, 0.5)[size // 2:], right=0.0)\n    alpha = np.sqrt(((size - 1) / (2 * ratio)) ** 2 / (-2 * np.log(gain)))\n    desired = np.exp(-(x * x + y * y) / (2 * alpha * alpha))\n    desired[desired < np.finfo(desired.dtype).eps * desired.max()] = 0\n    desired /= desired.max()\n    return np.real(np.fft.fftshift(np.fft.ifft2(np.fft.ifftshift(desired))) * window)\n\n\nclass WaldDegradation:\n    """Dataset-consistent x4 degradation of (PAN, MS) on full scenes."""\n\n    def __init__(self, sensor=\'QB\', device=\'cpu\'):\n        self.ms = SensorObservation(sensor, \'decimate\', (2, 2)).to(device).double()\n        self.pan_kernel = torch.from_numpy(_pan_kernel(PAN_GNYQ[sensor])[None, None]).to(device).double()\n        self.device = device\n\n    def pan(self, pan):\n        pad = self.pan_kernel.shape[-1] // 2\n        rows = torch.arange(-pad, pan.shape[-2] + pad, device=pan.device).clamp(0, pan.shape[-2] - 1)\n        cols = torch.arange(-pad, pan.shape[-1] + pad, device=pan.device).clamp(0, pan.shape[-1] - 1)\n        blurred = F.conv2d(pan.index_select(-2, rows).index_select(-1, cols), self.pan_kernel)\n        return blurred[..., 2::RATIO, 2::RATIO]\n\n    def __call__(self, pan_dn, ms_dn):\n        """numpy DN arrays (1,H,W) and (C,h,w) -> degraded (pan, lms, ms) numpy DN arrays."""\n        with torch.no_grad():\n            p = torch.from_numpy(np.asarray(pan_dn, dtype=np.float64))[None].to(self.device)\n            m = torch.from_numpy(np.asarray(ms_dn, dtype=np.float64))[None].to(self.device)\n            pan_b = self.pan(p); ms_b = self.ms(m)\n            lms_b = interp23tap((ms_b / 2047).float()).double() * 2047\n        return pan_b[0].cpu().numpy(), lms_b[0].cpu().numpy(), ms_b[0].cpu().numpy()\n\n\ndef observation_rmse(fused_dn, ms_dn, observation, margin=OBS_MARGIN):\n    with torch.no_grad():\n        f = torch.from_numpy(np.asarray(fused_dn, dtype=np.float64))[None].to(observation.kernel.device)\n        e = observation(f.to(observation.kernel.dtype))[0].cpu().numpy() - np.asarray(ms_dn, dtype=np.float64)\n    return float(np.sqrt(np.mean(e[..., margin:-margin, margin:-margin] ** 2)))\n\n\ndef predict(net, pan_dn, lms_dn, ms_dn, device):\n    x = [torch.from_numpy((np.asarray(a, dtype=np.float64) / 2047).astype(\'float32\')).unsqueeze(0).to(device) for a in (pan_dn, lms_dn, ms_dn)]\n    with torch.no_grad():\n        y = net(*x)\n    out = y[0].float().cpu().numpy().astype(np.float64) * 2047\n    if not np.isfinite(out).all():\n        raise FloatingPointError(\'nonfinite prediction\')\n    return out\n\n\ndef scene_metrics(net, rr_scene, fr_scene, device, degrade, observation):\n    """All criteria-v2 metrics for one RR scene and one FR scene (DN numpy dicts with pan/lms/ms[/gt])."""\n    out = {}\n    pred = predict(net, rr_scene[\'pan\'], rr_scene[\'lms\'], rr_scene[\'ms\'], device)\n    out[\'RR\'] = rr_metrics(rr_scene[\'gt\'], pred)\n    pan_b, lms_b, ms_b = degrade(rr_scene[\'pan\'], rr_scene[\'ms\'])\n    out[\'RR2\'] = rr_metrics(rr_scene[\'ms\'], predict(net, pan_b, lms_b, ms_b, device))\n    pan_b, lms_b, ms_b = degrade(fr_scene[\'pan\'], fr_scene[\'ms\'])\n    out[\'FR_WALD\'] = rr_metrics(fr_scene[\'ms\'], predict(net, pan_b, lms_b, ms_b, device))\n    fused = predict(net, fr_scene[\'pan\'], fr_scene[\'lms\'], fr_scene[\'ms\'], device)\n    out[\'FR\'] = fr_metrics(fused, fr_scene[\'lms\'], fr_scene[\'ms\'], fr_scene[\'pan\'])\n    out[\'FR\'][\'OBS_RMSE_DN\'] = observation_rmse(fused, fr_scene[\'ms\'], observation)\n    return out\n', 'common/observation.py': '"""Differentiable RR MS observation using the MATLAB DLPan MTF protocol.\n\nDLPan-Toolbox at a34f884af88967580e3ef4f61a89e12fdfe4cda5:\nTools/genMTF.m, MTF.m, resize_images.m. Radial Kaiser window follows\nMathWorks fwind1\'s documented Huang construction. Training-only audits\nverify sampling and patch interiors; this does not establish FR sensor physics.\n"""\nimport hashlib\nimport json\nfrom pathlib import Path\n\nimport numpy as np\nimport torch\nfrom torch import nn\nfrom torch.nn import functional as F\n\nSOURCE_COMMIT = "a34f884af88967580e3ef4f61a89e12fdfe4cda5"\nGNYQ = {\n    "QB": [0.34, 0.32, 0.30, 0.22],\n    "WV3": [0.325, 0.355, 0.360, 0.350, 0.365, 0.360, 0.335, 0.315],\n}\n\n\ndef module_hash():\n    return hashlib.sha256(Path(__file__).read_bytes()).hexdigest()\n\n\ndef mtf_kernels(sensor, ratio=4, size=41):\n    """Return MATLAB-protocol real FIR kernels (C,1,N,N), including signed taps."""\n    if sensor not in GNYQ:\n        raise ValueError(f"No sourced GNyq coefficients for {sensor}; do not assume GF2=IKONOS")\n    if ratio != 4 or size != 41:\n        raise ValueError("Only audited x4, 41-tap kernels supported")\n    coordinate = np.arange(size) - (size - 1) / 2\n    y, x = np.meshgrid(coordinate, coordinate, indexing="ij")\n    radial_window = np.interp(np.sqrt(x*x+y*y), np.arange(size//2+1),\n                              np.kaiser(size, 0.5)[size//2:], right=0.0)\n    kernels = []\n    for gain in GNYQ[sensor]:\n        alpha = np.sqrt(((size - 1) / (2 * ratio)) ** 2 / (-2 * np.log(gain)))\n        desired = np.exp(-(x*x+y*y)/(2*alpha*alpha))\n        desired[desired < np.finfo(desired.dtype).eps*desired.max()] = 0\n        desired /= desired.max()\n        # MATLAB fwind1: inverse frequency response times radial 1-D window.\n        # Keep signed taps and DC gain; clipping/renormalizing changes the operator.\n        impulse = np.fft.fftshift(np.fft.ifft2(np.fft.ifftshift(desired))) * radial_window\n        kernels.append(np.real(impulse))\n    return np.stack(kernels)[:, None].astype(np.float64)\n\n\nclass SensorObservation(nn.Module):\n    def __init__(self, sensor, sampling="decimate", phase=(2, 2), ratio=4):\n        super().__init__()\n        if sampling not in ("decimate", "bicubic"):\n            raise ValueError("Unknown sampling")\n        if len(phase) != 2 or any(v not in range(ratio) for v in phase):\n            raise ValueError("Invalid sampling phase")\n        self.sensor, self.sampling, self.phase, self.ratio = sensor, sampling, tuple(phase), ratio\n        self.register_buffer("kernel", torch.from_numpy(mtf_kernels(sensor, ratio)))\n\n    def blur(self, prediction):\n        if prediction.ndim != 4 or prediction.shape[1] != self.kernel.shape[0]:\n            raise ValueError("Expected NCHW with the sensor\'s bands")\n        if any(n % self.ratio for n in prediction.shape[-2:]):\n            raise ValueError("Spatial dimensions must be divisible by ratio")\n        # Replication implemented using index_select: deterministic CUDA backward,\n        # unlike replication_pad2d backward on some PyTorch versions.\n        padding = self.kernel.shape[-1] // 2\n        rows = torch.arange(-padding, prediction.shape[-2]+padding, device=prediction.device).clamp(0,prediction.shape[-2]-1)\n        cols = torch.arange(-padding, prediction.shape[-1]+padding, device=prediction.device).clamp(0,prediction.shape[-1]-1)\n        padded = prediction.index_select(-2, rows).index_select(-1, cols)\n        return F.conv2d(padded, self.kernel.to(dtype=prediction.dtype), groups=prediction.shape[1])\n\n    def sample(self, blurred):\n        if self.sampling == "bicubic":\n            return F.interpolate(blurred, scale_factor=1/self.ratio, mode="bicubic", align_corners=False, antialias=False)\n        return blurred[..., self.phase[0]::self.ratio, self.phase[1]::self.ratio]\n\n    def forward(self, prediction):\n        return self.sample(self.blur(prediction))\n\n    def loss(self, prediction, ms, margin, phases=None):\n        if phases is None:\n            observed = self(prediction)\n        else:\n            blurred = self.blur(prediction)\n            if len(phases) != len(prediction):\n                raise ValueError("Phase batch mismatch")\n            # Phases are fixed by original TRAIN pairs, never inferred from predictions.\n            observed = torch.cat([blurred[i:i+1, :, int(p[0])::self.ratio, int(p[1])::self.ratio]\n                                  for i, p in enumerate(phases)], dim=0)\n        if observed.shape != ms.shape:\n            raise ValueError("Observed prediction and MS shape differ")\n        if margin < 0 or min(ms.shape[-2:]) <= 2*margin:\n            raise ValueError("Invalid audited LR interior margin")\n        if margin:\n            observed = observed[..., margin:-margin, margin:-margin]\n            ms = ms[..., margin:-margin, margin:-margin]\n        return F.mse_loss(observed, ms)\n\n\ndef load_profile(path, expected_sha256=None, sensor=None, train_path=None):\n    path = Path(path)\n    content = path.read_bytes()\n    if expected_sha256 and hashlib.sha256(content).hexdigest() != expected_sha256:\n        raise ValueError("Observation profile hash changed")\n    profile = json.loads(content)\n    if profile.get("status") != "validated":\n        raise ValueError("Observation data audit has not passed")\n    if profile.get("operator_sha256") != module_hash():\n        raise ValueError("Observation code changed since audit")\n    if sensor and profile["sensor"] != sensor:\n        raise ValueError("Observation profile sensor mismatch")\n    if train_path and Path(profile["train_path"]).resolve() != Path(train_path).resolve():\n        raise ValueError("Observation profile dataset mismatch")\n    stat = Path(profile["train_path"]).stat()\n    if stat.st_size != profile["train_stat"]["size"] or stat.st_mtime_ns != profile["train_stat"]["mtime_ns"]:\n        raise ValueError("Training file changed since observation audit")\n    if profile.get("phase_policy") != "fixed_per_training_sample" or len(profile.get("phases",[])) != profile["sample_count"] or profile.get("coverage") != profile["sample_count"]:\n        raise ValueError("Training phase manifest incomplete")\n    if any(list(p) not in [[2,2],[1,2],[2,1]] for p in profile["phases"]):\n        raise ValueError("Unverified phase in manifest")\n    operator = SensorObservation(profile["sensor"],profile["sampling"],ratio=profile["ratio"])\n    return operator, profile\n', 'common/interpolation.py': '"""Differentiable channelwise toolbox-style 23-tap LMS interpolation."""\nimport math\nimport torch\nfrom torch import nn\nfrom torch.nn import functional as F\n\n\ndef interp23tap(image, ratio=4):\n    if image.ndim != 4 or ratio < 1 or ratio & (ratio-1):\n        raise ValueError(\'Expected NCHW input and power-of-two interpolation ratio\')\n    # Same coefficients, periodic boundary and insertion phases as metrics._interp23tap.\n    half = [.5,.305334091185,0,-.072698593239,0,.021809577942,\n            0,-.005192756653,0,.000807762146,0,-.000060081482]\n    with torch.autocast(image.device.type, enabled=False):\n        image=image.float()\n        kernel=image.new_tensor(half[:0:-1]+half)*2\n        channels=image.shape[1]\n        vertical=kernel.view(1,1,23,1).expand(channels,1,23,1).contiguous()\n        horizontal=kernel.view(1,1,1,23).expand(channels,1,1,23).contiguous()\n        for stage in range(int(math.log2(ratio))):\n            n,c,h,w=image.shape\n            up=image.new_zeros(n,c,h*2,w*2)\n            offset=1 if stage==0 else 0\n            up[:,:,offset::2,offset::2]=image\n            rows=torch.arange(-11,h*2+11,device=image.device)%(h*2)\n            cols=torch.arange(-11,w*2+11,device=image.device)%(w*2)\n            image=F.conv2d(up.index_select(2,rows),vertical,groups=c)\n            image=F.conv2d(image.index_select(3,cols),horizontal,groups=c)\n    return image\n\n\nclass Interp23(nn.Module):\n    def __init__(self,ratio):\n        super().__init__();self.ratio=ratio\n    def forward(self,x):\n        return interp23tap(x,self.ratio)\n', 'criteria_v2_2.md': '# 성능 개선 판정 기준 (v2.2)\n\n모든 연구 분야의 현재 실험 표에 이 기준을 적용합니다. 기존 실험은 [성능 47번](../experiments/performance/47_ground_truth_criteria_reevaluation/README.md)의 보존된 측정값으로 [현재 표 판정](../experiments/performance/47_ground_truth_criteria_reevaluation/results/summary_v2_2.json)을 다시 계산합니다. 47번에서 측정 전에 고정했던 v2 판정과 원본 수치는 보존하며, 현재 표의 v2.2 판정과 구분합니다. 새 학습이나 추론으로 결과를 바꾸지 않습니다.\n\n## 왜 바꿨나\n\n- [성능 46번](../experiments/performance/46_fr_spatial_index_validity/README.md): QB에서 FR Ds(Toolbox 1.0·원 논문 방식 모두)가 정답을 모델 출력보다 나쁘게 채점했습니다. 이 지표로 거부권을 행사하면 실제로 좋아진 결과를 탈락시킬 수 있습니다.\n- [성능 47번](../experiments/performance/47_ground_truth_criteria_reevaluation/README.md): 후보 96개에서 ΔQNR과 정답 기반 FR 장면 시험(FR_WALD)의 ΔPSNR은 순위 상관 −0.10으로 거의 무관했습니다.\n\n그래서 판정은 정답이 있는 시험으로만 하고, QNR·Dλ·Ds는 문헌 비교용으로만 보고합니다.\n\n## 판정 항목\n\n| 구분 | 시험 | 통과 조건 |\n|---|---|---|\n| 주 판정 | RR: PanCollection RR test 20장 | 같은 조건 대조군 대비 시드 평균 ΔPSNR > 0, ΔSAM < 0, ΔERGAS < 0 |\n| 보조 1 | RR2: RR 장면을 같은 Wald 열화로 한 번 더 1/4 축소, 정답 = RR MS | 시드 평균 ΔPSNR ≥ −0.05 dB, ΔSAM ≤ +0.06° |\n| 보조 2 | FR_WALD: FR 장면을 같은 열화로 1/4 축소, 정답 = 실제 FR MS | 시드 평균 ΔPSNR ≥ −0.07 dB, ΔSAM ≤ +0.04° |\n| 보조 3 | FR_OBS: FR 출력을 MS 관측 연산자로 줄였을 때 실제 FR MS와의 내부 RMSE(DN, 가장자리 5화소 제외) | 대조군 대비 1.10배 이하 |\n| 참고 | FR QNR·Dλ·Ds, RR SCC·Q2n, RR2·FR_WALD ERGAS | 판정에 쓰지 않고 보고만 함 |\n\n열화·보간·관측 연산은 [common/evaluation_protocol.py](../common/evaluation_protocol.py)를 사용합니다. [성능 47번 run.py](../experiments/performance/47_ground_truth_criteria_reevaluation/run.py)의 `judge`는 보존된 v2 재평가용입니다. 새 실험은 이 문서의 평균 판정 방식과 허용폭을 따릅니다.\n\n## 시드 수와 집계\n\n- 단일 시드도 주 판정과 보조 판정 3개를 모두 통과하면 **개선**으로 표기합니다. 개선 표기에 3시드 이상을 요구하지 않습니다.\n- 단일 시드는 해당 시드의 값을 사용합니다. 여러 시드는 같은 조건 대조군과 짝지은 전체 시드의 지표를 각각 산술평균한 뒤 후보 − 대조군 차이로 판정합니다. FR_OBS는 후보의 시드 평균 RMSE를 대조군의 시드 평균 RMSE로 나눈 비율입니다.\n- 여러 시드 중 하나만 통과했다고 전체를 개선으로 표기하지 않습니다. 평균이 모든 항목을 통과하면 개선이며, 과반 시드의 PSNR 개선을 추가로 요구하지 않습니다.\n- 사전에 정한 비교 시드를 일부 제외하거나 유리한 시드만 고르지 않습니다. 예정된 평가가 끝나지 않았다면 판단 보류로 표기합니다.\n- 시드 수와 시드 ID, 시드별 결과, 여러 시드의 평균을 함께 보고합니다. 단일 시드의 개선을 여러 시드에서 재현된 결과로 해석하지 않습니다.\n\n## 판정 이름\n\n| 판정 | 조건 |\n|---|---|\n| 개선 | 단일 시드 값 또는 여러 시드 평균이 주 판정과 보조 판정 3개를 모두 통과 |\n| 부분 개선 | 주 판정은 통과했지만 보조 판정 중 하나 이상 미달, 또는 PSNR·SAM·ERGAS 중 일부만 개선 |\n| 개선 없음 | PSNR·SAM·ERGAS 모두 개선 없음 |\n| 판단 보류 | 최종 RR·FR 평가가 끝나지 않음 |\n| 비교 기준·성능 비교 아님 | 판정 대상 아님 |\n\n보조 판정에서 미달했다면 확인된 결과에 어느 항목인지(예: "RR2 SAM +0.10°")를 적습니다.\n\n## 채택과 보고\n\n- 개선 표기와 기준 모델 교체를 구분합니다. 기준 모델 교체에는 3시드 이상에서 평균 판정이 "개선"이어야 합니다. 단일 시드 결과만으로 기준 모델을 교체하지 않습니다.\n- 후보와 가중치는 validation으로 고르고, test로 다시 고르지 않습니다. 어떤 후보도 자동 승격하지 않습니다.\n- 새 FR 지표는 성능 46번의 정답 순위 검사(정답이 가장 좋은 점수를 받는지)를 통과해야 판정에 넣을 수 있습니다.\n- 다른 센서·배율에 적용할 때는 같은 열화를 그 센서의 MTF로 바꾸고, 허용폭도 그 조건의 시드 편차로 다시 정합니다.\n\n## 허용폭 근거 (v2 → v2.1)\n\nv2는 RR의 시드 표준편차(PSNR 0.056 dB, SAM 0.021°)로 보조 판정 허용폭을 정했습니다. 성능 47번에서 각 시험의 시드 편차를 직접 재 보니, RR2와 FR_WALD의 SAM 편차가 그보다 컸습니다. v2.1은 각 시험의 허용폭을 그 시험 자체의 잡음 크기에 맞춥니다.\n\n| 시험 | 3시드 대조군 4개(성능 6, 33·38, 39, 43)의 시드 표준편차 | 중앙값 | v2.1 허용폭 |\n|---|---|---:|---:|\n| RR2 PSNR | 0.084 · 0.051 · 0.025 · 0.037 dB | 0.044 | −0.05 dB |\n| RR2 SAM | 0.035 · 0.096 · 0.077 · 0.037° | 0.057 | +0.06° |\n| FR_WALD PSNR | 0.070 · 0.026 · 0.089 · 0.052 dB | 0.061 | −0.07 dB |\n| FR_WALD SAM | 0.035 · 0.046 · 0.030 · 0.019° | 0.032 | +0.04° |\n\n허용폭은 중앙값을 0.01 단위로 올림한 값입니다. 47번 결과를 본 뒤 정한 값이므로 47번 판정에는 소급 적용하지 않습니다. 참고로 v2.1을 47번 후보에 적용하면 "개선"이 6개에서 10개(44 F2, 17 S1, SSAI 1 A1, SSAI 12 B3 추가, 모두 단일 시드)로 늘고, 43 C2·C3·29 W2·33·38 N1의 RR2 미달은 그대로입니다.\n\n## 시드 판정 변경 (v2.1 → v2.2)\n\n단일 시드도 모든 판정 항목을 통과하면 개선으로 표기한다는 점을 명시했습니다. 여러 시드는 전체 시드 평균으로 판정하며, 기존의 과반 시드 PSNR 개선 조건은 제거했습니다. 보조 판정 허용폭과 기준 모델 교체의 3시드 조건은 유지합니다. 47번의 원래 v2 판정은 보존하고 현재 실험 표에는 같은 측정값으로 계산한 v2.2 판정을 적용합니다.\n\n## 기존 실험 표에 반영하는 방법\n\n- [현재 표 판정](../experiments/performance/47_ground_truth_criteria_reevaluation/results/summary_v2_2.json)은 후보 96개의 동일한 시드 평균 차이와 관측 오차 비율에 v2.2를 적용한 결과입니다. 개선 10개·부분 개선 53개·개선 없음 33개이며, 개선 10개는 모두 단일 시드입니다.\n- 여러 후보가 있는 실험 표의 개선 여부는 후보별 판정 중 가장 높은 단계로 요약하고, 확인된 결과 열에 해당 후보를 적습니다. 다른 후보까지 개선됐다는 뜻이나 test로 최종 모델을 다시 선택한다는 뜻이 아닙니다.\n- QB 재평가 판정은 다른 센서·배율로 확대하지 않습니다. 33·38번은 합친 3시드 평균 판정을 두 표에 동일하게 반영합니다.\n- 평가 범위에서 제외됐거나 보조 판정이 없는 성능 비교는 판단 보류로 표시하고 부족한 근거를 적습니다. 구조 검사·관측 분석은 성능 비교 아님, 원본 기준선은 비교 기준으로 유지합니다.\n- 개별 실험의 원래 보고서와 47번의 v2 표는 작성 당시 기록입니다. 현재 판정은 연구별 표와 현재 표 판정 JSON을 함께 확인합니다.\n- 판정 재계산은 `python SSA-MRN/experiments/performance/47_ground_truth_criteria_reevaluation/prepare.py`로 재현합니다. 이 명령은 보존된 `results/summary.json`을 읽고 `results/summary_v2_2.json`만 생성합니다.\n', 'hf_gate_model.py': '"""C2 W2 control versus feature-frequency selective attenuation. No test metadata."""\nimport torch\nfrom torch import nn\nfrom torch.nn import functional as F\nfrom reference43 import Model as Reference43\n\nEPS=1e-8\n\ndef lowpass(x):\n    # Feature-domain binomial blur, NOT the sensor MS observation operator.\n    with torch.autocast(x.device.type,enabled=False):\n        x=x.float();c=x.shape[1];k=x.new_tensor([1,4,6,4,1])/16\n        x=F.conv2d(F.pad(x,(2,2,0,0),mode=\'reflect\'),k.view(1,1,1,5).expand(c,1,1,5),groups=c)\n        return F.conv2d(F.pad(x,(0,0,2,2),mode=\'reflect\'),k.view(1,1,5,1).expand(c,1,5,1),groups=c)\n\ndef energy_ratio(low,high):\n    a=low.square().mean((1,2,3));b=high.square().mean((1,2,3))\n    return b/(a+b+EPS)\n\nclass FrequencyParallel(nn.Module):\n    def __init__(self,parallel,arm):\n        super().__init__();self.original=parallel.original;self.branch=parallel.branch;self.arm=arm\n        # Separate RNG: adding gate parameters cannot perturb the C2 initialization.\n        with torch.random.fork_rng(devices=[]):\n            torch.manual_seed(20261020);self.gate=nn.Sequential(nn.Linear(2,8),nn.SiLU(),nn.Linear(8,1))\n        nn.init.zeros_(self.gate[-1].weight);nn.init.zeros_(self.gate[-1].bias)\n        self.last_gate=None;self.last_features=None\n    def forward(self,x):\n        original=self.original(x);b=self.branch(x)\n        if self.arm==\'baseline\':return original+b\n        with torch.autocast(x.device.type,enabled=False):\n            low=lowpass(b);high=b.float()-low;xl=lowpass(x)\n            # Detached, per-sample scalar features; no batch pooling or GT dependence.\n            features=torch.stack((energy_ratio(low,high),energy_ratio(xl,x.float()-xl)),dim=1).detach()\n            g=torch.sigmoid(self.gate(features)).view(-1,1,1,1)\n            self.last_gate=g.detach();self.last_features=features.detach()\n            delta=low+g*high\n            return original+delta.to(b.dtype)\n\nclass Model(nn.Module):\n    def __init__(self,arm=\'baseline\',seed=42):\n        super().__init__()\n        if arm not in (\'baseline\',\'hf_gate\'):raise ValueError(arm)\n        self.arm=arm;ref=Reference43(\'C2\',seed=seed);self.core=ref.core\n        self.core.backbone=FrequencyParallel(self.core.backbone,arm)\n    def forward(self,pan,lms,ms):return self.core(pan,lms,ms)\n    def gate_snapshot(self):\n        b=self.core.backbone\n        if b.last_gate is None:return {\'applied\':False,\'scope\':\'baseline bypass or not yet forwarded\'}\n        return {\'applied\':True,\'scope\':\'most recent forward only\',\'mean\':float(b.last_gate.mean()),\n                \'min\':float(b.last_gate.min()),\'max\':float(b.last_gate.max())}\n\ndef common_state(model):return model.state_dict()\ndef load_common(model,state):model.load_state_dict(state,strict=True)\ndef architecture_spec(arm):\n    if arm not in (\'baseline\',\'hf_gate\'):raise ValueError(arm)\n    return {\'arm\':arm,\'base\':\'43 C2: original N0 plus W2\',\'change\':\'B_low + sigmoid(MLP(detached relative energies))*B_high\' if arm==\'hf_gate\' else \'original+B; gate bypass\',\n            \'filter\':[1,4,6,4,1],\'filter_denominator\':16,\'filter_boundary\':\'reflect, separable, no downsampling\',\n            \'epsilon\':EPS,\'gate\':\'2->8->1 SiLU/sigmoid, per sample, common across all feature channels/pixels\',\n            \'initial_gate\':.5,\'gate_parameters\':33,\'initial_outputs_expected_equal\':True,\n            \'baseline_extra_parameters\':\'same 33 gate parameters present but unused; no gradient/Adam state for them\',\n            \'feature_blur_is_sensor_MTF\':False,\'parameters\':2853951}\n', 'hf_gate_judgement.py': '"""Pure v2.2 decision from paired seed means; test never selects settings."""\nimport math\n\ndef judge(baseline,candidate):\n    delta={s:{k:candidate[s][k]-baseline[s][k] for k in baseline[s]} for s in baseline}\n    ratio=candidate[\'FR\'][\'OBS_RMSE_DN\']/baseline[\'FR\'][\'OBS_RMSE_DN\'] if baseline[\'FR\'][\'OBS_RMSE_DN\']>0 else (1. if candidate[\'FR\'][\'OBS_RMSE_DN\']==0 else None)\n    primary=delta[\'RR\'][\'PSNR\']>0 and delta[\'RR\'][\'SAM\']<0 and delta[\'RR\'][\'ERGAS\']<0\n    guards={\'RR2\':delta[\'RR2\'][\'PSNR\']>=-.05 and delta[\'RR2\'][\'SAM\']<=.06,\n            \'FR_WALD\':delta[\'FR_WALD\'][\'PSNR\']>=-.07 and delta[\'FR_WALD\'][\'SAM\']<=.04,\n            \'FR_OBS\':ratio is not None and ratio<=1.10}\n    some=delta[\'RR\'][\'PSNR\']>0 or delta[\'RR\'][\'SAM\']<0 or delta[\'RR\'][\'ERGAS\']<0\n    return {\'criteria_version\':\'v2.2\',\'delta\':delta,\'observation_ratio\':ratio,\'primary\':primary,\'guards\':guards,\n            \'label\':\'개선\' if primary and all(guards.values()) else (\'부분 개선\' if some else \'개선 없음\'),\n            \'QNR_used_for_decision\':False,\'FR_ground_truth_available\':False}\n', 'hf_gate_worker.py': '"""W2 feature high-frequency selective attenuation; common MSE training protocol."""\nimport os\nos.environ.setdefault(\'CUBLAS_WORKSPACE_CONFIG\', \':4096:8\')\nimport argparse, hashlib, json, math, random, signal, time\nfrom datetime import datetime, timedelta, timezone\nfrom pathlib import Path\nimport numpy as np\nimport h5py\nimport torch\nfrom torch.nn import functional as F\nfrom hf_gate_model import Model, load_common, common_state\nfrom hf_gate_model import architecture_spec\n\nSTOP = False\nKST = timezone(timedelta(hours=9))\nKEYS = (\'pan\', \'lms\', \'ms\', \'gt\')\n\ndef stop_handler(*_):\n    global STOP\n    STOP = True\n\ndef atomic_json(path, value):\n    tmp = path.with_suffix(path.suffix+\'.tmp\')\n    tmp.write_text(json.dumps(value, indent=2, allow_nan=False), encoding=\'utf-8\')\n    os.replace(tmp, path)\n\ndef atomic_save(path, value):\n    tmp = path.with_suffix(\'.tmp\')\n    with open(tmp, \'wb\') as file:\n        torch.save(value, file)\n        file.flush()\n        os.fsync(file.fileno())\n    os.replace(tmp, path)\n\ndef file_hash(path):\n    h = hashlib.sha256()\n    with open(path, \'rb\') as file:\n        for block in iter(lambda:file.read(8<<20), b\'\'):\n            h.update(block)\n    return h.hexdigest()\n\ndef state_hash(state):\n    h = hashlib.sha256()\n    for key, value in sorted(state.items()):\n        h.update(key.encode()); h.update(str(value.dtype).encode())\n        h.update(str(tuple(value.shape)).encode())\n        h.update(value.detach().cpu().contiguous().numpy().tobytes())\n    return h.hexdigest()\n\ndef cpu_state(model):\n    return {k:v.detach().cpu().clone() for k,v in model.state_dict().items()}\n\ndef load_resident(config):\n    """No hidden CPU fallback: train and validation stay on this worker\'s GPU."""\n    result = {}\n    required = sum(config[\'data\'][s][\'resident_fp32_bytes\'] for s in (\'train\',\'val\'))\n    free, total = torch.cuda.mem_get_info()\n    if free-required < config[\'reserve_gib\']*(1<<30):\n        raise RuntimeError(f\'GPU resident data need {required/(1<<30):.2f} GiB; \'\n                           f\'free={free/(1<<30):.2f}, reserve={config["reserve_gib"]} GiB. \'\n                           \'No CPU fallback. Reduce BOTH model micro batches in a NEW run, \'\n                           \'or use a documented new data-residency plan.\')\n    for split in (\'train\',\'val\'):\n        result[split] = {}\n        with h5py.File(config[\'data\'][split][\'path\'],\'r\') as h:\n            n = config[\'data\'][split][\'used_samples\']\n            for key in KEYS:\n                shape = (n,)+tuple(h[key].shape[1:])\n                target = torch.empty(shape, device=\'cuda\', dtype=torch.float32)\n                # Chunked staging avoids holding the entire H5 twice in CPU RAM.\n                for start in range(0,n,64):\n                    array = np.asarray(h[key][start:min(n,start+64)],dtype=np.float32)\n                    if not np.isfinite(array).all():\n                        raise ValueError(f\'{split}/{key}: nonfinite data\')\n                    target[start:start+len(array)].copy_(torch.from_numpy(array / 2047.))\n                result[split][key] = target\n    torch.cuda.synchronize()\n    return result\n\ndef validate(model,data,batch):\n    """Unmodified inputs; full archived33 MSE/PSNR/SAM, fixed first32 auxiliary metrics."""\n    from common.metrics import rr_metrics\n    model.eval();s=torch.zeros(4,device=\'cuda\',dtype=torch.float64);inner_elements=0\n    pixels=torch.zeros((),device=\'cuda\',dtype=torch.int64);n=0;elements=0;rows=[]\n    with torch.inference_mode():\n        for start in range(0,len(data[\'pan\']),batch):\n            b={k:v[start:start+batch] for k,v in data.items()};gt=b[\'gt\']\n            p=model(b[\'pan\'],b[\'lms\'],b[\'ms\']).float()\n            if not torch.isfinite(p).all():raise FloatingPointError(\'Nonfinite validation\')\n            error=(p-gt).square();s[0]+=error.double().sum();elements+=gt.numel()\n            inner=error[...,4:-4,4:-4];s[3]+=inner.double().sum();inner_elements+=inner.numel()\n            s[1]+=(-10*torch.log10(error.mean((2,3)).clamp_min(1e-15))).mean(1).double().sum();n+=len(gt)\n            norm=p.norm(dim=1)*gt.norm(dim=1);mask=norm>1e-12\n            cos=(p*gt).sum(1)/norm.clamp_min(1e-12)\n            s[2]+=torch.acos(cos.clamp(-1,1))[mask].double().sum();pixels+=mask.sum()\n            if start<32:\n                a=p[:32-start].cpu().numpy().astype(np.float64)*2047.;g=gt[:32-start].cpu().numpy().astype(np.float64)*2047.\n                rows.extend(rr_metrics(x,y) for x,y in zip(g,a))\n    a=s.cpu().tolist();model.train()\n    return {\'mse\':a[0]/elements,\'psnr\':a[1]/n,\'sam\':math.degrees(a[2]/max(int(pixels),1)),\n            \'mse_inner4\':a[3]/inner_elements,\'mse_border4\':(a[0]-a[3])/(elements-inner_elements),\n            **{k.lower():float(np.mean([r[k] for r in rows])) for k in (\'ERGAS\',\'SCC\',\'Q2n\')},\n            \'evaluation_policy\':{\'applied\':False,\'scope\':\'unmodified validation inputs; no training or test-time augmentation\'}}\n\n\n\n\n\n\n\n\n\n\ndef panels(arrays, pred, path, scene, protocol=\'RR full scene\'):\n    import matplotlib\n    matplotlib.use(\'Agg\')\n    import matplotlib.pyplot as plt\n    rgb_bands = [2,1,0]\n    ref = arrays[\'gt\'][rgb_bands].transpose(1,2,0)\n    low, high = np.percentile(ref,(1,99),axis=(0,1))\n    def rgb(a):\n        return np.clip((a[rgb_bands].transpose(1,2,0)-low)/np.maximum(high-low,1e-8),0,1)\n    fig,axes = plt.subplots(1,4,figsize=(16,4))\n    images = [rgb(arrays[\'ms\']),arrays[\'pan\'][0],rgb(pred),rgb(arrays[\'gt\'])]\n    for ax,title,image in zip(axes,(\'LR MS (nearest)\',\'PAN input\',\'Prediction\',\'GT\'),images):\n        ax.imshow(image, interpolation=\'nearest\', cmap=\'gray\' if image.ndim==2 else None)\n        ax.set_title(title); ax.axis(\'off\')\n    fig.suptitle(f\'{protocol} {scene} | same GT-derived MS contrast\')\n    fig.tight_layout(); fig.savefig(path,dpi=130); plt.close(fig)\n\ndef evaluate(config, folder, model, report):\n    import sys\n    sys.path.insert(0,str(Path(config[\'code_root\'])/\'SSA-MRN/src\'))\n    from common.metrics import rr_metrics, fr_metrics\n    eval_name=config.get(\'eval_checkpoint\',\'best\')\n    ck = torch.load(folder/(eval_name+\'.pt\'),map_location=\'cpu\',weights_only=False)\n    if ck[\'fingerprint\'] != config[\'fingerprint\']:\n        raise ValueError(\'Best fingerprint mismatch\')\n    model.load_state_dict(ck[\'model\'],strict=True); model.eval()\n    checkpoint_folder=folder\n    folder=folder/\'evaluations\'/eval_name; folder.mkdir(parents=True,exist_ok=True)\n    results = {\'best_epoch\':ck[\'epoch\'], \'best_val_mse\':ck.get(\'mse\',ck.get(\'best_mse\')), \'full_scene\':True,\n               \'test_precision\':\'FP32\', \'checkpoint_kind\':eval_name, \'limitations\':\'FR D_s/QNR MATLAB parity is unverified; RR Q2n/SCC parity is unverified.\',\n               \'splits\':{}}\n    from common.evaluation_protocol import WaldDegradation,observation_rmse\n    from common.observation import SensorObservation\n    smoke=bool(config.get(\'smoke_evaluation\'))\n    degrade=WaldDegradation(\'QB\',\'cuda\') if not smoke else None\n    observation=SensorObservation(\'QB\',\'decimate\',(2,2)).cuda().double() if not smoke else None\n    inference_times=[];warmed_forward={};gate_records={}\n    for split in ((\'RR\',\'FR\') if smoke else (\'RR\',\'RR2\',\'FR_WALD\',\'FR\')):\n        rows=[]; tick=time.monotonic()\n        # Smoke checks use validation inputs only; held-out RR/FR are never scored here.\n        entry=config[\'data\'][\'val\'] if config.get(\'smoke_evaluation\') else config[\'data\'][\'RR\' if split==\'RR2\' else (\'FR\' if split==\'FR_WALD\' else split)]\n        with h5py.File(entry[\'path\'],\'r\') as h:\n            indices=range(min(2,len(h[\'pan\']))) if config.get(\'smoke_evaluation\') else range(len(h[\'pan\']))\n            for index in indices:\n                report(stage=\'evaluate_\'+split,scene=index+1,scenes=len(h[\'pan\']),\n                       train_eta_kst=None,total_eta_kst=None,eta_scope=\'test scoring/I/O unmeasured\')\n                keys = KEYS if split==\'RR\' else KEYS[:3]\n                arrays={k:np.asarray(h[k][index],dtype=np.float64) for k in keys}\n                if split in (\'RR2\',\'FR_WALD\'):\n                    gt=arrays[\'ms\'].copy()\n                    pp,ll,mm=degrade(arrays[\'pan\'],arrays[\'ms\'])\n                    arrays={\'pan\':pp,\'lms\':ll,\'ms\':mm,\'gt\':gt}\n                inputs=[torch.from_numpy((arrays[k]/2047.).astype(np.float32)).unsqueeze(0).cuda() for k in KEYS[:3]]\n                if index==0:\n                    with torch.inference_mode():\n                        for _ in range(3):model(*inputs)\n                        probe=[]\n                        for _ in range(5):\n                            torch.cuda.synchronize();t=time.monotonic();model(*inputs);torch.cuda.synchronize();probe.append(time.monotonic()-t)\n                    warmed_forward[split]={\'median_ms\':1000*float(np.median(probe)),\'warmup\':3,\'repetitions\':5,\'scope\':\'first scene only; transfer/metrics excluded\'}\n                torch.cuda.synchronize(); infer_tick=time.monotonic()\n                with torch.inference_mode():\n                    gpu_pred=model(*inputs)[0].float()\n                torch.cuda.synchronize(); infer_seconds=time.monotonic()-infer_tick\n                inference_times.append({\'split\':split,\'scene_index\':index,\'seconds\':infer_seconds,\n                                        \'scope\':\'FP32 forward only; first-scene probe performed; transfer/metrics excluded\'})\n                pred=gpu_pred.cpu().numpy().astype(np.float64)*2047.\n                if not np.isfinite(pred).all():\n                    raise RuntimeError(\'Nonfinite test prediction\')\n                metrics=rr_metrics(arrays[\'gt\'],pred) if split!=\'FR\' else fr_metrics(pred,arrays[\'lms\'],arrays[\'ms\'],arrays[\'pan\'])\n                if split==\'FR\' and not smoke:metrics[\'OBS_RMSE_DN\']=observation_rmse(pred,arrays[\'ms\'],observation)\n                gate_records.setdefault(split,[]).append({\'scene_index\':index,**model.gate_snapshot()})\n                if split==\'RR\':\n                    err=((pred.astype(np.float64)-arrays[\'gt\'])/2047.)**2\n                    metrics[\'MSE_peak1\']=float(err.mean())\n                    inner=err[...,4:-4,4:-4]\n                    metrics[\'MSE_inner4_peak1\']=float(inner.mean())\n                    metrics[\'MSE_border4_peak1\']=float((err.sum()-inner.sum())/(err.size-inner.size))\n                    if index in config[\'selection\'][\'indices\']:\n                        panels(arrays,pred,folder/f\'RR_scene_{index:03}.png\',index)\n                if not all(math.isfinite(float(v)) for v in metrics.values()):\n                    raise RuntimeError(\'Nonfinite test metric\')\n                rows.append({\'scene_index\':index, **metrics})\n                atomic_json(folder/f\'{split}_per_scene.json\',rows)\n                del inputs\n        results[\'splits\'][split]={\'count\':len(rows),\'seconds\':time.monotonic()-tick,\n                                 \'mean\':{k:float(np.mean([r[k] for r in rows])) for k in rows[0] if k!=\'scene_index\'}}\n    results[\'smoke_validation_inputs_only\']=bool(config.get(\'smoke_evaluation\'))\n    results[\'gate_records\']=gate_records\n    results[\'criteria_version\']=\'v2.2\'\n    results[\'inference_times\']=inference_times\n    results[\'warmed_forward\']=warmed_forward\n    results[\'test_input_policy\']=\'unmodified native inputs; RR2/FR_WALD use pinned evaluation protocol; only W2 frequency-selective gate differs\'\n    results[\'peak_gpu_gib\']=torch.cuda.max_memory_allocated()/(1<<30)\n    results[\'checkpoints\']={k:{\'sha256\':file_hash(checkpoint_folder/f\'{k}.pt\')} for k in (\'best\',\'latest\')}\n    results[\'evaluation_protocol_sha256\']=file_hash(Path(config[\'code_root\'])/\'common/evaluation_protocol.py\')\n    atomic_json(folder/\'results.json\',results)\n    atomic_json(folder/\'evaluation_complete.json\',{\'RR\':results[\'splits\'][\'RR\'][\'count\'],\'FR\':results[\'splits\'][\'FR\'][\'count\'],\n                \'fingerprint\':config[\'fingerprint\'],\'best_sha256\':file_hash(checkpoint_folder/\'best.pt\'),\n                \'latest_sha256\':file_hash(checkpoint_folder/\'latest.pt\'),\'results_sha256\':file_hash(folder/\'results.json\')})\n\ndef train(config, label, physical_gpu):\n    import sys\n    sys.path.insert(0,str(Path(config[\'code_root\'])/\'SSA-MRN/src\'))\n    from hf_gate_model import Model\n    folder=Path(config[\'output\'])/label; folder.mkdir(exist_ok=True)\n    signal.signal(signal.SIGTERM,stop_handler); signal.signal(signal.SIGINT,stop_handler)\n    assert torch.cuda.device_count()==1, \'Each process must see exactly one GPU\'\n    global STOP\n    STOP = False\n    torch.set_num_threads(1)\n    torch.use_deterministic_algorithms(True,warn_only=not config.get(\'smoke_deterministic\',False))\n    torch.backends.cudnn.benchmark=False\n    torch.backends.cudnn.deterministic=True\n    torch.backends.cuda.matmul.allow_tf32=False\n    torch.backends.cudnn.allow_tf32=False\n    random.seed(config[\'seed\']); np.random.seed(config[\'seed\']); torch.manual_seed(config[\'seed\'])\n    torch.cuda.manual_seed_all(config[\'seed\'])\n    def report(**kw):\n        value={\'label\':label,\'physical_gpu\':physical_gpu,\'k\':4,\'total_epochs\':config[\'epochs\'],\n               \'updated_kst\':datetime.now(KST).isoformat(),\n               \'allocated_gib\':torch.cuda.memory_allocated()/(1<<30),\n               \'reserved_gib\':torch.cuda.memory_reserved()/(1<<30),\n               \'peak_gib\':torch.cuda.max_memory_allocated()/(1<<30),**kw}\n        atomic_json(folder/\'status.json\',value)\n        with open(folder/\'progress.jsonl\',\'a\',encoding=\'utf-8\') as file:\n            file.write(json.dumps(value,allow_nan=False)+\'\\n\')\n        print(json.dumps(value,ensure_ascii=False),flush=True)\n    report(stage=\'load_gpu_data\',train_eta_kst=None,total_eta_kst=None,eta_scope=\'measurement pending\')\n    data=load_resident(config) if config.get(\'job_type\')!=\'test\' else None\n    model=Model(config[\'arm\'],seed=config[\'seed\']).cuda()\n    initial=torch.load(Path(config[\'output\'])/\'initial.pt\',map_location=\'cpu\',weights_only=True)\n    load_common(model,initial)\n    initial_hash=state_hash(model.state_dict())\n    atomic_json(folder/\'initialization.json\',{\'state_sha256\':initial_hash,\n        \'common_state_sha256\':state_hash(common_state(model)), \'model\':\'43_C2_W2_with_same_inactive_or_active_gate\',\n        \'parameters\':sum(p.numel() for p in model.parameters()), \'initial_outputs_expected_equal\':True,\'spatial_operator\':architecture_spec(config[\'arm\']), \'k\':4})\n    opt=torch.optim.Adam(model.parameters(),lr=config[\'lr\'])\n    stepped=[False]\n    opt.register_step_post_hook(lambda *_:stepped.__setitem__(0,True))\n    scaler=torch.amp.GradScaler(\'cuda\',enabled=config[\'amp\'],init_scale=1024.)\n    generator=torch.Generator(device=\'cuda\').manual_seed(config[\'seed\']+100000) # archived33 stream; separate model/sampler RNG\n    n=len(data[\'train\'][\'gt\']) if data is not None else 0; batch=config[\'batch\']; micro=config[\'micro\']\n    groups=math.ceil(n/batch)\n    epoch=0; position=0; order=None; order_hash=None; best=None; best_payload=None\n    history=[]; orders=[]; timings=[]\n    total=torch.zeros((),device=\'cuda\',dtype=torch.float64); count=0; skipped=0\n    # Save only at completed optimizer-step boundaries; no partial gradients.\n    active_train_seconds=0.; training_timer=None\n    def checkpoint():\n        nonlocal last_save, active_train_seconds, training_timer\n        if training_timer is not None:\n            torch.cuda.synchronize()\n            active_train_seconds+=time.monotonic()-training_timer\n            training_timer=time.monotonic()\n        rng={\'python\':random.getstate(),\'numpy\':np.random.get_state(),\'cpu\':torch.get_rng_state(),\n             \'cuda\':torch.cuda.get_rng_state(),\'generator\':generator.get_state()}\n        state={\'fingerprint\':config[\'fingerprint\'],\'config\':config[\'conditions\'],\n               \'model\':cpu_state(model),\'optimizer\':opt.state_dict(),\'scaler\':scaler.state_dict(),\n               \'lr_schedule\':{\'type\':\'constant\',\'lr\':config[\'lr\']},\'rng\':rng,\n               \'epoch\':epoch,\'next_sample_position\':position,\'order\':None if order is None else order.cpu(),\n               \'order_hash\':order_hash,\'order_history\':orders,\'loss_sse\':total.cpu(),\'loss_elements\':count,\n               \'history\':history,\'timings\':timings,\'best_mse\':best,\'best_payload\':best_payload,\n               \'initial_state_sha256\':initial_hash,\'skipped_amp_steps\':skipped,\n               \'active_train_seconds\':active_train_seconds}\n        atomic_save(folder/\'latest.pt\',state)\n        # Preserve the actual historical best, even at non-improving epochs.\n        if best_payload is not None:\n            atomic_save(folder/\'best.pt\',best_payload)\n        atomic_json(folder/\'history.json\',history)\n        atomic_json(folder/\'orders.json\',orders)\n        last_save=time.monotonic()\n    if config.get(\'job_type\')==\'test\':\n        for kind in (\'best\',\'latest\'):\n            evaluate(dict(config,eval_checkpoint=kind),folder,model,report)\n        atomic_json(folder/\'evaluation_complete.json\',{\'fingerprint\':config[\'fingerprint\'],\n            \'best_sha256\':file_hash(folder/\'best.pt\'),\'latest_sha256\':file_hash(folder/\'latest.pt\'),\n            \'results_sha256\':{k:file_hash(folder/\'evaluations\'/k/\'results.json\') for k in (\'best\',\'latest\')}})\n        report(stage=\'evaluation_complete\')\n        return\n    if (folder/\'latest.pt\').exists():\n        ck=torch.load(folder/\'latest.pt\',map_location=\'cpu\',weights_only=False)\n        if ck[\'fingerprint\']!=config[\'fingerprint\'] or ck[\'initial_state_sha256\']!=initial_hash:\n            raise ValueError(\'Resume conditions/initial state mismatch; use a new run\')\n        model.load_state_dict(ck[\'model\']); opt.load_state_dict(ck[\'optimizer\']); scaler.load_state_dict(ck[\'scaler\'])\n        epoch=ck[\'epoch\']; position=ck[\'next_sample_position\']; order=ck[\'order\']\n        if order is not None: order=order.cuda()\n        order_hash=ck[\'order_hash\']; orders=ck[\'order_history\']; history=ck[\'history\']; timings=ck[\'timings\']\n        total=ck[\'loss_sse\'].cuda(); count=ck[\'loss_elements\']; best=ck[\'best_mse\']; best_payload=ck[\'best_payload\']\n        skipped=ck[\'skipped_amp_steps\']\n        active_train_seconds=ck[\'active_train_seconds\']\n        r=ck[\'rng\']; random.setstate(r[\'python\']); np.random.set_state(r[\'numpy\'])\n        torch.set_rng_state(r[\'cpu\']); torch.cuda.set_rng_state(r[\'cuda\']); generator.set_state(r[\'generator\'])\n    # Include epoch0 in best selection exactly as archived33. Never choose using test.\n    if best is None:\n        initial_val=validate(model,data[\'val\'],micro)\n        best=initial_val[\'mse\']\n        best_payload={\'fingerprint\':config[\'fingerprint\'],\'model\':cpu_state(model),\'epoch\':0,\n                      \'mse\':best,\'validation\':initial_val,\'config\':config[\'conditions\']}\n        history=[{\'epoch\':0,\'lr\':config[\'lr\'],\'train_mse\':None,\'train_total\':None,\n                  **{\'val_\'+k:v for k,v in initial_val.items() if k!=\'evaluation_policy\'},\n                  \'evaluation_policy\':initial_val[\'evaluation_policy\'],\'validation_diagnostic_scope\':\'ERGAS/SCC/Q2n: fixed first32 val; MSE/PSNR/SAM: full used val\'}]\n    last_save=time.monotonic(); checkpoint()\n    last_log=0.; model.train()\n    while epoch<config[\'epochs\']:\n        if STOP or time.time()>=config[\'deadline\']:\n            checkpoint(); report(stage=\'paused\',epoch=epoch,next_sample_position=position); return\n        tick=time.monotonic(); training_timer=tick; segment_start=position; steps_done=0\n        if order is None:\n            order=torch.randperm(n,device=\'cuda\',generator=generator)\n            order_hash=hashlib.sha256(order.cpu().numpy().tobytes()).hexdigest()\n            orders.append({\'epoch\':epoch+1,\'order_sha256\':order_hash})\n            atomic_json(folder/\'orders.json\',orders)\n            checkpoint()\n        for start in range(position,n,batch):\n            end=min(n,start+batch); opt.zero_grad(set_to_none=True)\n            group_ids=order[start:end]\n            for offset in range(start,end,micro):\n                ids=order[offset:min(end,offset+micro)]\n                b={k:v.index_select(0,ids) for k,v in data[\'train\'].items()}\n                with torch.autocast(\'cuda\',dtype=torch.float16,enabled=config[\'amp\']):\n                    pred=model(b[\'pan\'],b[\'lms\'],b[\'ms\'])\n                squared=(pred.float()-b[\'gt\']).square().sum() # FP32 outside autocast, archived33 operation\n                # Deliberately no per-batch .item()/CPU transfers.\n                total+=squared.detach().double()\n                count+=b[\'gt\'].numel()\n                group_loss=squared/((end-start)*data[\'train\'][\'gt\'][0].numel())\n                scaler.scale(group_loss).backward()\n            stepped[0]=False\n            scaler.step(opt); scaler.update()\n            skipped+=int(not stepped[0])\n            position=end; steps_done+=1\n            if time.monotonic()-last_save>=60:\n                checkpoint()\n            if STOP or time.time()>=config[\'deadline\'] or (config.get(\'stop_after_group\') and math.ceil(position/batch)>=config[\'stop_after_group\']):\n                checkpoint(); report(stage=\'paused\',epoch=epoch,next_sample_position=position); return\n            if time.monotonic()-last_log>=config[\'log_seconds\']:\n                torch.cuda.synchronize(); elapsed=time.monotonic()-tick\n                remaining_groups=math.ceil((n-position)/batch)\n                remainder=remaining_groups*elapsed/max(steps_done,1)\n                eta=None\n                if timings:\n                    remainder+=float(np.mean([t[\'validation_save_seconds\'] for t in timings]))\n                    remainder+=(config[\'epochs\']-epoch-1)*float(np.mean([t[\'epoch_wall_seconds\'] for t in timings]))\n                    eta=(datetime.now(KST)+timedelta(seconds=remainder)).isoformat()\n                mse=float(total.cpu())/max(count,1)\n                if not math.isfinite(mse): raise RuntimeError(\'Nonfinite train MSE\')\n                report(stage=\'train\',epoch=epoch+1,batch=math.ceil(position/batch),batches=groups,\n                       lr=opt.param_groups[0][\'lr\'],train_mse=mse,train_total=mse,elapsed_seconds=elapsed,\n                       train_eta_kst=eta,total_eta_kst=None,\n                       eta_scope=\'measured train+val+save; test scoring, figures and ZIP excluded\' if eta else \'first epoch measurement pending\')\n                last_log=time.monotonic()\n        torch.cuda.synchronize(); train_time=time.monotonic()-tick\n        active_train_seconds+=time.monotonic()-training_timer; training_timer=None\n        report(stage=\'validation\',epoch=epoch+1,train_eta_kst=None,total_eta_kst=None)\n        val_tick=time.monotonic(); val=validate(model,data[\'val\'],micro)\n        torch.cuda.synchronize(); val_seconds=time.monotonic()-val_tick\n        mse=float(total.cpu())/count\n        if not math.isfinite(mse) or not all(math.isfinite(v) for k,v in val.items() if k!=\'evaluation_policy\'):\n            raise RuntimeError(\'Nonfinite epoch statistics\')\n        row={\'lr\':opt.param_groups[0][\'lr\'],\'epoch\':epoch+1,\'train_mse\':mse,\'val_mse\':val[\'mse\'],\'val_psnr\':val[\'psnr\'],\'val_sam\':val[\'sam\'],\n             \'skipped_amp_steps\':skipped,\'order_sha256\':order_hash,\'train_segment_seconds\':train_time,\n             \'validation_seconds\':val_seconds,\'resumed_mid_epoch\':segment_start>0,\n             \'train_total\':mse,\n             \'val_ergas\':val[\'ergas\'],\'val_scc\':val[\'scc\'],\'val_q2n\':val[\'q2n\']}\n        row[\'train_total\']=mse\n        row[\'validation_diagnostic_scope\']=\'ERGAS/SCC/Q2n: first 32 validation patches; MSE/PSNR/SAM: all used validation patches\'\n        row[\'evaluation_policy\']=val[\'evaluation_policy\']\n        row[\'val_mse_inner4\']=val[\'mse_inner4\'];row[\'val_mse_border4\']=val[\'mse_border4\']\n        history.append(row)\n        if best is None or val[\'mse\']<best:\n            best=val[\'mse\']; best_payload={\'fingerprint\':config[\'fingerprint\'],\'model\':cpu_state(model),\n                                         \'epoch\':epoch+1,\'mse\':best,\'validation\':val,\'config\':config[\'conditions\']}\n        epoch+=1; position=0; order=None; order_hash=None; total.zero_();count=0\n        save_tick=time.monotonic(); checkpoint(); save_seconds=time.monotonic()-save_tick\n        # Mid-epoch resumed segments are excluded from epoch-based ETA calibration.\n        if segment_start==0:\n            timings.append({\'epoch_wall_seconds\':time.monotonic()-tick,\n                            \'validation_save_seconds\':val_seconds+save_seconds})\n        atomic_json(folder/\'history.json\',history)\n        remaining=(config[\'epochs\']-epoch)*float(np.mean([t[\'epoch_wall_seconds\'] for t in timings])) if timings else None\n        report(stage=\'epoch_complete\',**row,train_eta_kst=(datetime.now(KST)+timedelta(seconds=remaining)).isoformat() if remaining is not None else None,\n               total_eta_kst=None,eta_scope=\'test scoring, figures and ZIP excluded\')\n    checkpoint()\n    completion_proof={\'epochs\':epoch,\'best_epoch\':best_payload[\'epoch\'],\'best_mse\':best,\n        \'fingerprint\':config[\'fingerprint\'],\'best_sha256\':file_hash(folder/\'best.pt\'),\'latest_sha256\':file_hash(folder/\'latest.pt\')}\n    # Free resident training arrays before full-scene FP32 evaluation.\n    del data, opt, scaler; torch.cuda.empty_cache()\n    atomic_json(folder/\'validation_result.json\',{\'best_epoch\':best_payload[\'epoch\'],\n                \'best_validation\':best_payload[\'validation\'],\'last_validation\':history[-1],\n                \'last_epoch\':epoch,\'peak_gpu_gib\':torch.cuda.max_memory_allocated()/(1<<30),\n                \'train_seconds_measured_segments\':sum(h.get(\'train_segment_seconds\',0.) for h in history),\n                \'train_active_seconds\':active_train_seconds,\n                \'timing_limit\':\'active train timer includes within-epoch checkpoint overhead; excludes data loading/validation; preserved across resume\'})\n    atomic_json(folder/\'training_complete.json\',completion_proof)\n    report(stage=\'training_complete_no_test\',epoch=epoch,train_eta_kst=datetime.now(KST).isoformat(),total_eta_kst=None)\n\ndef main():\n    parser=argparse.ArgumentParser(); parser.add_argument(\'--config\'); parser.add_argument(\'--label\'); parser.add_argument(\'--gpu\',type=int)\n    args=parser.parse_args(); config=json.loads(Path(args.config).read_text())\n    try:\n        train(config,args.label,args.gpu)\n    except Exception as exc:\n        folder=Path(config[\'output\'])/args.label; folder.mkdir(exist_ok=True)\n        atomic_json(folder/\'failure.json\',{\'error\':str(exc),\'type\':type(exc).__name__})\n        raise\n\nif __name__==\'__main__\':\n    main()\n', 'hf_gate_dashboard.py': '"""Notebook presentation only: never imports torch or changes worker/config state."""\nimport html\nimport json\nimport math\nimport subprocess\nimport time\nfrom datetime import datetime, timedelta, timezone\nfrom pathlib import Path\n\nSTAGES = {\'starting\': \'시작 준비\', \'load_gpu_data\': \'데이터 → GPU\', \'train\': \'학습\',\n          \'validation\': \'검증\', \'epoch_complete\': \'에폭 완료\', \'paused\': \'체크포인트 저장 · 일시정지\',\n          \'training_complete_no_test\': \'학습 완료 · test 미실행\', \'evaluate_RR\': \'RR 평가\',\n          \'evaluate_RR2\': \'RR2 추가 축소 평가\', \'evaluate_FR_WALD\': \'FR Wald 평가\', \'evaluate_FR\': \'FR 관측·참고 지표 평가\', \'evaluation_complete\': \'평가 완료\', \'error\': \'오류\',\n          \'interrupted\': \'중단\', \'idle\': \'대기\'}\nPHASES = {\'smoke\':\'소량 실행 · 저장/재개 점검\', \'final_train\':\'본 학습 · 현재 seed의 두 군\', \'final_test\':\'최종 RR·RR2·FR_WALD·FR 관측 평가\'}\n\n\ndef esc(value):\n    return html.escape(str(value), quote=True)\n\ndef number(value, digits=4):\n    try:\n        value = float(value)\n        return f\'{value:.{digits}g}\' if math.isfinite(value) else \'—\'\n    except (TypeError, ValueError):\n        return \'—\'\n\ndef progress(value):\n    try:\n        value = float(value)\n        if not math.isfinite(value): return \'<span class="muted">측정 대기</span>\'\n    except (TypeError, ValueError):\n        return \'<span class="muted">—</span>\'\n    value = max(0., min(100., value))\n    return f\'<div class="bar"><i style="width:{value:.1f}%"></i></div><small>{value:.1f}%</small>\'\n\ndef render(phase, rows, note=\'\', data_rows=(), gpu_stats=None, updated=\'\'):\n    gpu_stats = gpu_stats or {}\n    body, metric_body = [], []\n    for gpu in (0, 1):\n        row = rows.get(gpu, {})\n        v = row.get(\'status\', {})\n        stage = v.get(\'stage\', \'idle\')\n        epoch, epochs = v.get(\'epoch\'), row.get(\'epochs\')\n        batch, batches = v.get(\'batch\'), v.get(\'batches\')\n        fraction = None\n        if stage == \'train\' and batches:\n            fraction = 100 * batch / batches if batch is not None else None\n        elif stage in (\'validation\', \'epoch_complete\', \'training_complete_no_test\'):\n            fraction = 100\n        elif stage.startswith(\'evaluate_\') and v.get(\'scenes\'):\n            fraction = 100 * v.get(\'scene\', 0) / v[\'scenes\']\n        elif stage == \'evaluation_complete\':\n            fraction = 100\n        unit = \'장면\' if stage.startswith(\'evaluate_\') else \'배치\'\n        count = (f"{v.get(\'scene\', \'—\')}/{v.get(\'scenes\', \'—\')}" if unit == \'장면\'\n                 else f\'{batch}/{batches}\' if stage == \'train\' and batches else \'—\')\n        epoch_text = f\'{epoch}/{epochs}\' if epoch is not None and epochs else \'—\'\n        # On validation/terminal reports, loss/metrics may refer to the last observed report.\n        metrics = row.get(\'metrics\', {})\n        allocated = number(v.get(\'allocated_gib\'), 3)\n        peak = number(v.get(\'peak_gib\'), 3)\n        stats = gpu_stats.get(gpu, {})\n        device = f"{number(stats.get(\'used_gib\'), 3)} / {number(stats.get(\'total_gib\'), 3)} GiB"\n        util = number(stats.get(\'utilization\'), 3)\n        eta = v.get(\'train_eta_kst\')\n        try: eta = datetime.fromisoformat(eta).strftime(\'%m/%d %H:%M:%S\') if eta else \'측정 대기\'\n        except (ValueError, TypeError): eta = \'측정 대기\'\n        if stage in (\'training_complete_no_test\', \'evaluation_complete\'): eta = \'완료\'\n        elif stage in (\'paused\', \'error\', \'interrupted\', \'idle\') or stage.startswith(\'evaluate_\'): eta = \'—\'\n        badge = \'bad\' if stage in (\'error\', \'interrupted\') else \'good\' if stage in (\'training_complete_no_test\', \'evaluation_complete\') else \'\'\n        error = row.get(\'error\') or \'—\'\n        body.append(f\'\'\'<tr><td><b>GPU {gpu} · {esc(row.get(\'label\', \'baseline\' if gpu == 0 else \'hf_gate\'))}</b>\n          <small>{esc(row.get(\'context\', \'작업 대기\'))}</small><small>대기 작업 {esc(row.get(\'queued\', 0))}개</small></td>\n          <td><span class="badge {badge}">{esc(STAGES.get(stage, stage))}</span></td>\n          <td>{esc(epoch_text)}</td><td>{progress(fraction)}<small>{unit} {esc(count)}</small></td>\n          <td>{number(row.get(\'throughput\'), 4)}</td>\n          <td>{allocated} / {peak}<small>장치 {device}</small><small>사용률 {util}%</small></td>\n          <td class="error">{esc(error)}</td></tr>\'\'\')\n        metric_body.append(f\'<tr><td><b>GPU {gpu} · {esc(row.get("label", "baseline" if gpu == 0 else "hf_gate"))}</b></td>\' +\n                           \'\'.join(f\'<td>{number(metrics.get(key), 5)}</td>\' for key in\n                           (\'train_mse\', \'val_mse\', \'val_psnr\', \'val_sam\')) +\n                           f\'<td>{esc(eta)}<small>KST · 학습/검증/저장</small></td></tr>\')\n    dataset = \'\'\n    if data_rows:\n        dataset = \'<details><summary>데이터 확인 결과 · 상세 수치/해시는 data_manifest.json</summary><table><tr><th>분할</th><th>전체 / 사용 장면·패치</th><th>LMS 크기 (NCHW)</th><th>검사</th></tr>\'\n        for split, info in data_rows:\n            shape = info[\'arrays\'][\'lms\'][\'shape\']\n            dataset += f\'<tr><td>{esc(split)}</td><td>{shape[0]:,} / {info["used_samples"]:,}</td><td>{esc(" × ".join(map(str, shape)))}</td><td>유한값 · 범위 · SHA-256 확인</td></tr>\'\n        dataset += \'</table></details>\'\n    return \'\'\'<style>\n      .hf_gate-dashboard {font-family:system-ui,-apple-system,"Malgun Gothic",sans-serif;color:#172b4d;background:#fff;border:1px solid #dce4ef;border-radius:12px;padding:18px;margin:12px 0;font-size:13px;line-height:1.5}\n      .hf_gate-dashboard h3 {font-size:18px;margin:0 0 5px;color:#172b4d}.hf_gate-dashboard h4 {font-size:13px;margin:16px 0 0}.hf_gate-dashboard .muted,.hf_gate-dashboard small{color:#66758b}.hf_gate-dashboard small{display:block;font-size:11px}\n      .hf_gate-dashboard .scroll {overflow-x:auto}.hf_gate-dashboard table{width:100%;border-collapse:collapse;margin:12px 0;white-space:nowrap}\n      .hf_gate-dashboard th{background:#edf2f8;color:#34465e;font-weight:600;text-align:left;padding:10px 8px}\n      .hf_gate-dashboard td{padding:12px 8px;border-bottom:1px solid #e5ebf3;vertical-align:top}.hf_gate-dashboard tr:nth-child(even) td{background:#f8fafc}\n      .hf_gate-dashboard .badge{display:inline-block;padding:3px 7px;background:#eaf2ff;color:#2455a4;border-radius:5px}.hf_gate-dashboard .good{background:#e8f6ed;color:#237746}.hf_gate-dashboard .bad{background:#ffebeb;color:#a52626}\n      .hf_gate-dashboard .bar{width:92px;height:6px;background:#e1e8f2;border-radius:3px;overflow:hidden;margin:6px 0}.hf_gate-dashboard .bar i{display:block;height:100%;background:#427ee8}\n      .hf_gate-dashboard .notice{padding:9px 12px;background:#f0f5fb;border-radius:7px;margin:10px 0;white-space:pre-wrap;overflow-wrap:anywhere}\n      .hf_gate-dashboard .error{max-width:200px;min-width:40px;white-space:normal;overflow-wrap:anywhere;color:#a52626}.hf_gate-dashboard summary{cursor:pointer}\n      </style>\'\'\' + f\'\'\'<section class="hf_gate-dashboard"><h3>W2HFSelective_1st · {esc(PHASES.get(phase, phase))}</h3>\n      <span class="muted">K=4 · QuickBird · GPU0 W2 / GPU1 W2 HF selective · 갱신 {esc(updated or \'—\')}</span>\n      <div class="notice">{esc(note or \'준비 중\')}</div>{dataset}<div class="scroll"><table><thead><tr>\n      <th>실험</th><th>상태</th><th>에폭</th><th>현재 에폭 / 평가 진행</th>\n      <th>패치/초</th><th>모델 할당 / 최대 GiB</th><th>오류</th>\n      </tr></thead><tbody>{\'\'.join(body)}</tbody></table></div>\n      <h4>손실 · 최근 완료 Validation · 학습 종료 예상</h4><div class="scroll"><table><thead><tr>\n      <th>실험</th><th>Train MSE</th><th>Val MSE</th><th>Val PSNR</th><th>Val SAM</th><th>종료 예상</th>\n      </tr></thead><tbody>{\'\'.join(metric_body)}</tbody></table></div>\n      <small>손실은 최근 worker 보고값입니다. Validation은 최근 완료 에폭 값이며 best 값과 다를 수 있습니다. ERGAS·SCC·Q2n은 validation 앞32개 보조 지표입니다. 두 군은 W2·MSE가 같으며 변경군만 추가 특징의 고주파 주입량을 조절합니다.</small>\n      <small>패치/초는 같은 에폭의 두 학습 보고 사이에서 실측합니다. 첫 보고 전에는 —로 표시합니다. 장치 메모리는 다른 프로세스도 포함합니다.</small>\n      <small>종료 예상에는 대기 작업·test 평가·그림·ZIP 시간이 포함되지 않습니다. 상태 표는 약 5초마다, worker 손실/진행 보고는 약 20초마다 갱신됩니다.</small>\n      </section>\'\'\'\n\nclass Dashboard:\n    def __init__(self, phase, root):\n        self.phase, self.root = phase, Path(root)\n        self.rows = {0: {}, 1: {}}\n        self.data_rows, self.note, self.gpu_stats = [], \'데이터 검사 준비 중\', {}\n        self.handle = None\n        self.last_gpu = self.last_plain = 0.\n\n    def data_checked(self, split, info):\n        self.data_rows.append((split, info))\n        self.note = f\'{split} 검사 완료 · 전체 {info["arrays"]["lms"]["shape"][0]:,} / 사용 {info["used_samples"]:,}개\'\n        self.refresh()\n\n    def starting(self, job, queued):\n        g, config = job[\'gpu\'], job[\'config\']\n        self.rows[g] = {\'label\': job[\'label\'], \'epochs\': config[\'epochs\'], \'queued\': queued,\n                        \'samples\': config[\'data\'][\'train\'][\'used_samples\'], \'batch_size\': config[\'batch\'],\n                        \'context\': f\'{job["folder"].parent.name} · {config["arm"]} · {job["folder"].parent.parent.name}\',\n                        \'status\': {\'stage\': \'starting\'}, \'metrics\': {}, \'throughput\': None}\n\n    def observe(self, gpu, value):\n        row = self.rows[gpu]\n        previous = row.get(\'status\', {})\n        row[\'throughput\'] = None\n        if value.get(\'stage\') == previous.get(\'stage\') == \'train\' and value.get(\'epoch\') == previous.get(\'epoch\'):\n            try:\n                seconds = (datetime.fromisoformat(value[\'updated_kst\']) - datetime.fromisoformat(previous[\'updated_kst\'])).total_seconds()\n                # Report batch is an effective group; cap the final partial group\'s sample count.\n                count = row[\'samples\']\n                delta = min(value[\'batch\'] * row[\'batch_size\'], count) - min(previous[\'batch\'] * row[\'batch_size\'], count)\n                if seconds > 0 and delta > 0: row[\'throughput\'] = delta / seconds\n            except (ValueError, KeyError, TypeError): pass\n        row[\'status\'] = value\n        for key in (\'train_mse\', \'val_mse\', \'val_psnr\', \'val_sam\'):\n            if key in value: row[\'metrics\'][key] = value[key]\n\n    def finish(self, job, returncode=0, skipped=False):\n        g = job[\'gpu\']\n        row = self.rows[g]\n        if returncode:\n            row[\'status\'] = {**row.get(\'status\', {}), \'stage\': \'error\'}\n            row[\'error\'] = f\'종료 코드 {returncode} · {job["folder"].relative_to(self.root)}/worker.log 확인\'\n        else:\n            marker = \'evaluation_complete.json\' if job[\'config\'][\'job_type\'] == \'test\' else \'training_complete.json\'\n            complete = (job[\'folder\'] / marker).is_file()\n            name = (\'evaluation_complete\' if job[\'config\'][\'job_type\'] == \'test\' else \'training_complete_no_test\') if complete else \'paused\'\n            row[\'status\'] = {**row.get(\'status\', {}), \'stage\': name}\n            if complete and job[\'config\'][\'job_type\'] != \'test\': row[\'status\'][\'epoch\'] = job[\'config\'][\'epochs\']\n            if skipped: row[\'context\'] += \' · 저장된 완료 결과 확인\'\n        row[\'throughput\'] = None\n\n    def refresh(self, note=None, persist=True):\n        if note is not None: self.note = note\n        now = time.monotonic()\n        if now - self.last_gpu >= 5:\n            self.last_gpu = now\n            try:\n                raw = subprocess.check_output([\'nvidia-smi\', \'--query-gpu=index,memory.used,memory.total,utilization.gpu\',\n                                               \'--format=csv,noheader,nounits\'], text=True, stderr=subprocess.DEVNULL, timeout=2)\n                self.gpu_stats = {}\n                for line in raw.splitlines():\n                    gpu, used, total, utilization = map(float, line.split(\',\'))\n                    self.gpu_stats[int(gpu)] = {\'used_gib\': used / 1024, \'total_gib\': total / 1024, \'utilization\': utilization}\n            except (OSError, ValueError, subprocess.SubprocessError): self.gpu_stats = {}\n        value = render(self.phase, self.rows, self.note, self.data_rows, self.gpu_stats,\n                       datetime.now(timezone(timedelta(hours=9))).strftime(\'%m/%d %H:%M:%S KST\'))\n        # Snapshot file is supplementary; a presentation failure must not interrupt training.\n        if persist:\n            try: (self.root / \'live_dashboard.html\').write_text(value, encoding=\'utf-8\')\n            except OSError: pass\n        try:\n            from IPython import get_ipython\n            from IPython.display import HTML, display\n            if get_ipython() is None: raise ImportError(\'plain Python\')\n            if self.handle is None:\n                self.handle = display(HTML(value), display_id=True)\n                if self.handle is None: raise ImportError(\'no display update handle\')\n            else: self.handle.update(HTML(value))\n        except Exception:\n            if now - self.last_plain >= 20:\n                self.last_plain = now\n                print(self.note + \' | \' + \' | \'.join(f\'GPU{g} {r.get("label", "대기")}: {STAGES.get(r.get("status", {}).get("stage", "idle"), "대기")}\' for g, r in self.rows.items()), flush=True)\n'}
